def pump_messages():
    """Pump the Windows message queue to prevent 'Not Responding' during long JIT compilation.
    Lightweight — no rendering, just tells Windows the process is alive."""
    try:
        import ctypes
        from ctypes import wintypes
        msg = wintypes.MSG()
        PM_REMOVE = 0x0001
        while ctypes.windll.user32.PeekMessageW(ctypes.byref(msg), None, 0, 0, PM_REMOVE):
            ctypes.windll.user32.TranslateMessage(ctypes.byref(msg))
            ctypes.windll.user32.DispatchMessageW(ctypes.byref(msg))
    except Exception:
        pass

def safe_window_show(win):
    """Wrapper for window.show() that handles Vulkan swapchain errors during window move/resize"""
    pump_messages()
    try:
        win.show()
    except RuntimeError:
        pass  # Skip frame — swapchain will recover next frame

# ============================================================================
# FAST CLIPBOARD COPY (Windows only - using clip.exe)
# ============================================================================
def copy_to_clipboard(text):
    """Copy text to clipboard using clip.exe (non-blocking, no lag)"""
    try:
        import subprocess
        # Use clip.exe - built into Windows, handles any text size
        process = subprocess.Popen(
            'clip.exe',
            stdin=subprocess.PIPE,
            shell=True,
            creationflags=subprocess.CREATE_NO_WINDOW
        )
        process.stdin.write(text.encode('utf-8'))
        process.stdin.close()
        # Don't wait for process to finish - makes it non-blocking
        return True
    except Exception as e:
        print(f"[Clipboard] Error: {e}")
        return False

