# ============================================================================
# CONTROLLER SUPPORT
# ============================================================================
controllers = []  # List of connected Controller objects
STICK_DEADZONE = 0.4       # Forward/backward deadzone
STICK_TURN_DEADZONE = 0.32  # Turn deadzone (lower for responsive direction changes while charging)
TRIGGER_THRESHOLD = 0.3

# SDL Controller axis/button constants (raw integers for pygame compatibility)
AXIS_LEFTX = 0
AXIS_LEFTY = 1
AXIS_RIGHTX = 2
AXIS_RIGHTY = 3
AXIS_TRIGGERLEFT = 4
AXIS_TRIGGERRIGHT = 5
BUTTON_A = 0
BUTTON_B = 1
BUTTON_X = 2
BUTTON_Y = 3
BUTTON_LEFTSHOULDER = 9
BUTTON_RIGHTSHOULDER = 10

def init_controllers():
    """Initialize pygame controller subsystem. Call once at startup."""
    if not CONTROLLER_SUPPORT:
        return
    pygame.init()
    sdl_controller.init()
    _refresh_controllers()

def _refresh_controllers():
    """Rebuild controller list. Called on startup and device events."""
    global controllers
    # Close old controllers
    for ctrl in controllers:
        try:
            ctrl.quit()
        except:
            pass
    controllers = []
    for i in range(sdl_controller.get_count()):
        try:
            ctrl = sdl_controller.Controller(i)
            controllers.append(ctrl)
            print(f"[Controller] Found: {ctrl.name} (player {len(controllers)})")
        except:
            pass
    if not controllers:
        print("[Controller] No controllers detected")

def pump_controller_events():
    """Call once per frame. Handles hot-plug via events, ~0.01ms overhead."""
    if not CONTROLLER_SUPPORT:
        return
    try:
        for event in pygame.event.get():
            if event.type == pygame.CONTROLLERDEVICEADDED:
                print("[Controller] Device connected")
                _refresh_controllers()
            elif event.type == pygame.CONTROLLERDEVICEREMOVED:
                print("[Controller] Device disconnected")
                _refresh_controllers()
    except (SystemError, KeyError):
        # pygame/SDL can throw when controller connects/disconnects mid-frame
        print("[Controller] Hot-plug event error, refreshing controllers")
        _refresh_controllers()

def get_controller_inputs(ctrl, horn_type_id=0):
    """Read controller state and return input bitmask (same format as keyboard)."""
    if ctrl is None:
        return 0
    try:
        inputs = 0
        # Left stick: All movement (Y = forward/back, X = turn)
        left_y = ctrl.get_axis(AXIS_LEFTY) / 32767.0
        left_x = ctrl.get_axis(AXIS_LEFTX) / 32767.0
        if left_y < -STICK_DEADZONE:
            inputs |= INPUT_FORWARD
        elif left_y > STICK_DEADZONE:
            inputs |= INPUT_BACKWARD
        if left_x < -STICK_TURN_DEADZONE:
            inputs |= INPUT_LEFT
        elif left_x > STICK_TURN_DEADZONE:
            inputs |= INPUT_RIGHT

        # Right stick: Alternative horn controls (same mapping as XYAB)
        right_y = ctrl.get_axis(AXIS_RIGHTY) / 32767.0
        right_x = ctrl.get_axis(AXIS_RIGHTX) / 32767.0

        # Face buttons + right stick: Horn controls (beetle-specific remapping)
        # Right stick mirrors XYAB: up=Y, down=A, left=X, right=B
        button_y = ctrl.get_button(BUTTON_Y) or (right_y < -STICK_DEADZONE)
        button_a = ctrl.get_button(BUTTON_A) or (right_y > STICK_DEADZONE)
        button_x = ctrl.get_button(BUTTON_X) or (right_x < -STICK_DEADZONE)
        button_b = ctrl.get_button(BUTTON_B) or (right_x > STICK_DEADZONE)

        if horn_type_id == 0 or horn_type_id == 4:  # Rhino or Atlas: swap X/B for intuitive yaw
            # Y/A: up/down (same as default)
            if button_y:
                inputs |= INPUT_HORN_UP
            if button_a:
                inputs |= INPUT_HORN_DOWN
            # X/B: swapped for intuitive left/right sweep
            if button_x:
                inputs |= INPUT_HORN_RIGHT  # Swapped
            if button_b:
                inputs |= INPUT_HORN_LEFT   # Swapped
        elif horn_type_id == 5:  # Bombardier: Y/A=body, X/B=fire
            # Y/A: body up/down
            if button_y:
                inputs |= INPUT_HORN_LEFT   # Body up
            if button_a:
                inputs |= INPUT_HORN_RIGHT  # Body down
            # X/B: fire direction
            if button_x:
                inputs |= INPUT_HORN_DOWN   # Fire behind
            if button_b:
                inputs |= INPUT_HORN_UP     # Fire forward
        elif horn_type_id == 6:  # Spider: Y/A=body, X/B=silk type
            # Y/A: body up/down
            if button_y:
                inputs |= INPUT_HORN_LEFT   # Body up
            if button_a:
                inputs |= INPUT_HORN_RIGHT  # Body down
            # X/B: silk type
            if button_x:
                inputs |= INPUT_HORN_DOWN   # Normal silk
            if button_b:
                inputs |= INPUT_HORN_UP     # Fast silk
        else:  # Stag, Hercules, Scorpion - default mapping
            if button_y:
                inputs |= INPUT_HORN_UP
            if button_a:
                inputs |= INPUT_HORN_DOWN
            if button_x:
                inputs |= INPUT_HORN_LEFT
            if button_b:
                inputs |= INPUT_HORN_RIGHT
        return inputs
    except:
        return 0  # Controller disconnected or error

def _get_keyboard_inputs(window, player='blue', network_mode=False, horn_type_id=0):
    """
    Read keyboard inputs and return 8-bit input state.

    This abstraction allows:
    - Easy addition of controller support later
    - Network sync (just send the 8-bit value)
    - Input replay/recording
    - Key remapping

    Args:
        window: The game window to read key presses from
        player: 'blue' or 'red' to select key bindings
        network_mode: If True, use WASD + arrow keys instead of split keyboard
        horn_type_id: Beetle type for network mode arrow key remapping

    Returns:
        int: 8-bit input state (0-255)
    """
    if network_mode:
        keys = NETWORK_KEYS
    else:
        keys = BLUE_KEYS if player == 'blue' else RED_KEYS
    inputs = 0

    # Movement keys (same for all beetle types)
    if window.is_pressed(keys['forward']):
        inputs |= INPUT_FORWARD
    if window.is_pressed(keys['backward']):
        inputs |= INPUT_BACKWARD
    if window.is_pressed(keys['left']):
        inputs |= INPUT_LEFT
    if window.is_pressed(keys['right']):
        inputs |= INPUT_RIGHT

    if network_mode:
        # Beetle-specific arrow key remapping for intuitive controls
        if horn_type_id == 0 or horn_type_id == 4:  # Rhino or Atlas: swap LEFT<->RIGHT for intuitive yaw
            if window.is_pressed(ti.GUI.UP):
                inputs |= INPUT_HORN_UP
            if window.is_pressed(ti.GUI.DOWN):
                inputs |= INPUT_HORN_DOWN
            if window.is_pressed(ti.GUI.LEFT):
                inputs |= INPUT_HORN_RIGHT  # Swapped
            if window.is_pressed(ti.GUI.RIGHT):
                inputs |= INPUT_HORN_LEFT   # Swapped
        elif horn_type_id == 5:  # Bombardier: UP/DOWN=body, LEFT/RIGHT=fire
            if window.is_pressed(ti.GUI.UP):
                inputs |= INPUT_HORN_LEFT   # Body up
            if window.is_pressed(ti.GUI.DOWN):
                inputs |= INPUT_HORN_RIGHT  # Body down
            if window.is_pressed(ti.GUI.LEFT):
                inputs |= INPUT_HORN_DOWN   # Fire behind
            if window.is_pressed(ti.GUI.RIGHT):
                inputs |= INPUT_HORN_UP     # Fire forward
        elif horn_type_id == 6:  # Spider: UP/DOWN=body, LEFT/RIGHT=silk types
            if window.is_pressed(ti.GUI.UP):
                inputs |= INPUT_HORN_LEFT   # Body up
            if window.is_pressed(ti.GUI.DOWN):
                inputs |= INPUT_HORN_RIGHT  # Body down
            if window.is_pressed(ti.GUI.LEFT):
                inputs |= INPUT_HORN_DOWN   # Normal silk
            if window.is_pressed(ti.GUI.RIGHT):
                inputs |= INPUT_HORN_UP     # Fast silk
        else:  # Stag, Hercules, Scorpion - default mapping
            if window.is_pressed(keys['horn_up']):
                inputs |= INPUT_HORN_UP
            if window.is_pressed(keys['horn_down']):
                inputs |= INPUT_HORN_DOWN
            if window.is_pressed(keys['horn_left']):
                inputs |= INPUT_HORN_LEFT
            if window.is_pressed(keys['horn_right']):
                inputs |= INPUT_HORN_RIGHT
    else:
        # Local mode - standard mapping
        if window.is_pressed(keys['horn_up']):
            inputs |= INPUT_HORN_UP
        if window.is_pressed(keys['horn_down']):
            inputs |= INPUT_HORN_DOWN
        if window.is_pressed(keys['horn_left']):
            inputs |= INPUT_HORN_LEFT
        if window.is_pressed(keys['horn_right']):
            inputs |= INPUT_HORN_RIGHT

    return inputs


def get_local_inputs(window, player='blue', network_mode=False, horn_type_id=0):
    """Get inputs from controller (if available) combined with keyboard."""
    # Get keyboard inputs (always works)
    keyboard_inputs = _get_keyboard_inputs(window, player, network_mode, horn_type_id)

    # Add controller inputs if available
    controller_inputs = 0
    if CONTROLLER_SUPPORT and controllers:
        if network_mode:
            # Network mode: first controller controls local beetle
            controller_inputs = get_controller_inputs(controllers[0], horn_type_id)
        elif player == 'blue':
            controller_inputs = get_controller_inputs(controllers[0], horn_type_id)
        elif player == 'red' and len(controllers) >= 2:
            controller_inputs = get_controller_inputs(controllers[1], horn_type_id)

    # Combine both input sources (allows hybrid play)
    return keyboard_inputs | controller_inputs


# ===== Bot AI (local --local4 slots 2/3; NOT used in network play) ===========
# Structured as _bot_observe() -> get_bot_inputs() so the heuristic can later
# be swapped for a trained policy behind the same observation (see plan for
# training bots on real levels). Per-bot persistent state carries a heading-
# noise random walk, a stuck-detector history, short break/feint timers, a
# held horn move, and a fixed personality so slots 2 and 3 differ. Bots are
# local-only, so this nondeterminism is safe (no host/guest desync).
_bot_ai_state = {}

def _bot_state(slot):
    st = _bot_ai_state.get(slot)
    if st is None:
        rng = random.Random((slot * 100003) ^ (int(time.time() * 1000) & 0xffffff))
        st = {
            'rng': rng,
            'wander': 0.0,        # heading-noise random walk (rad)
            'hist': [],           # sampled positions for stuck detection
            'break_timer': 0,     # frames left in a disengage/unstick maneuver
            'break_turn': 1,      # turn direction during a break
            'feint_timer': 0,     # frames left in a feint juke
            'horn': 0,            # currently held horn move
            'horn_timer': 0,      # frames left holding it
            'pers': {
                'wander_max': rng.uniform(0.25, 0.60),  # how curvy the charges are
                'edge_caution': rng.uniform(6.0, 10.0), # how early to flee the rim (units)
                'charge_cone': rng.uniform(1.00, 1.30), # facing tolerance to commit forward
                'aggression': rng.uniform(0.55, 1.00),  # horn frequency / commitment
            },
        }
        _bot_ai_state[slot] = st
    return st

def _wrap_pi(a):
    a = a % (2.0 * math.pi)
    if a > math.pi:
        a -= 2.0 * math.pi
    return a

def _bot_observe(slot):
    """Build the observation a trained policy would also consume: own edge
    situation + nearest opponent. Circular arena, so distance-to-rim is just
    ARENA_RADIUS - |pos|. (For non-circular training levels this should read
    the arena SDF instead.)"""
    b = beetles[slot]
    dist_c = math.hypot(b.x, b.z)
    if dist_c > 0.01:
        ux, uz = b.x / dist_c, b.z / dist_c
    else:
        ux, uz = math.cos(b.rotation), math.sin(b.rotation)
    best, best_d2 = None, 1e18
    for other in range(active_player_count):
        if other == slot:
            continue
        ob = beetles[other]
        if not ob.active or ob.is_falling:
            continue
        d2 = (ob.x - b.x) ** 2 + (ob.z - b.z) ** 2
        if d2 < best_d2:
            best_d2, best = d2, ob
    return {
        'b': b,
        'dist_center': dist_c,
        'margin': ARENA_RADIUS - dist_c,        # distance to the rim
        'radial_out': b.vx * ux + b.vz * uz,    # >0 = drifting toward the rim
        'to_center_ang': math.atan2(-b.z, -b.x),
        'target': best,
        'target_d2': best_d2,
    }

def get_bot_inputs(slot):
    """Bot input driver for local --local4 slots 2/3. Modes: idle, random,
    seek (default). 'seek' adds edge-avoidance with strategic reverse, heading
    noise, and stuck/loop breaking so bots stop looping and stop self-ejecting."""
    b = beetles[slot]
    if not b.active or b.is_falling or hovering[slot]:
        return 0
    if BOT_AI_MODE == "idle":
        return 0
    if BOT_AI_MODE == "random":
        phase = int((time.time() * 0.66 + slot * 7.3)) % 4
        return (INPUT_FORWARD, INPUT_FORWARD | INPUT_LEFT,
                INPUT_FORWARD, INPUT_FORWARD | INPUT_RIGHT)[phase]

    st = _bot_state(slot)
    rng = st['rng']
    p = st['pers']
    obs = _bot_observe(slot)
    margin = obs['margin']
    radial_out = obs['radial_out']
    center_diff = _wrap_pi(obs['to_center_ang'] - b.rotation)  # turn needed to face center
    inputs = 0

    # Heading-noise random walk — drifts the charge angle so approaches curve
    # and two bots never re-derive an identical head-on orbit.
    st['wander'] += rng.uniform(-0.05, 0.05)
    st['wander'] = max(-p['wander_max'], min(p['wander_max'], st['wander']))

    # Stuck detector: sample position every 12 frames, keep a ~1.6s window.
    if physics_frame % 12 == 0:
        st['hist'].append((b.x, b.z))
        if len(st['hist']) > 8:
            st['hist'].pop(0)

    # --- Priority 1: EDGE DANGER — flee to center, REVERSE if facing the rim.
    # Triggered by proximity, or by drifting outward fast a bit further in.
    danger = margin < p['edge_caution'] or (margin < p['edge_caution'] * 1.9 and radial_out > 3.5)
    if danger:
        st['break_timer'] = 0  # edge overrides any in-progress maneuver
        if center_diff > 0.10:
            inputs |= INPUT_RIGHT
        elif center_diff < -0.10:
            inputs |= INPUT_LEFT
        if abs(center_diff) < 1.4:
            inputs |= INPUT_FORWARD    # already facing inward — drive to safety
        else:
            inputs |= INPUT_BACKWARD   # facing the rim — back away rather than turn into it
        return inputs

    # --- Priority 2: active break maneuver (reverse out of a loop/shove).
    if st['break_timer'] > 0:
        st['break_timer'] -= 1
        inputs |= INPUT_BACKWARD
        inputs |= INPUT_RIGHT if st['break_turn'] > 0 else INPUT_LEFT
        return inputs

    target = obs['target']
    if target is None:
        # No one to fight: ease back toward center, don't thrash.
        if abs(center_diff) > 0.2:
            inputs |= INPUT_RIGHT if center_diff > 0 else INPUT_LEFT
        if abs(center_diff) < 1.2 and obs['dist_center'] > 6.0:
            inputs |= INPUT_FORWARD
        return inputs

    # Detect a stuck shove (little movement over the window with a foe close) and
    # break it by reversing + turning a random way to re-approach from elsewhere.
    if len(st['hist']) >= 8:
        ox, oz = st['hist'][0]
        if math.hypot(b.x - ox, b.z - oz) < 3.0 and obs['target_d2'] < 900:
            st['break_timer'] = rng.randint(22, 34)
            st['break_turn'] = 1 if rng.random() < 0.5 else -1
            inputs |= INPUT_BACKWARD
            inputs |= INPUT_RIGHT if st['break_turn'] > 0 else INPUT_LEFT
            return inputs

    # --- Normal seek, with heading noise so the charge isn't dead straight.
    want = math.atan2(target.z - b.z, target.x - b.x) + st['wander']
    diff = _wrap_pi(want - b.rotation)
    if abs(diff) < p['charge_cone']:
        inputs |= INPUT_FORWARD
    if diff > 0.12:
        inputs |= INPUT_RIGHT
    elif diff < -0.12:
        inputs |= INPUT_LEFT

    # Strategic reverse in melee: if we're being out-shoved toward the rim, stop
    # pushing and back off to reset the angle instead of riding it to the edge.
    if obs['target_d2'] < 1400 and radial_out > 3.0 and margin < 16.0:
        inputs &= ~INPUT_FORWARD
        inputs |= INPUT_BACKWARD

    # Occasional feint: a brief reverse juke to bait/be unpredictable.
    if st['feint_timer'] > 0:
        st['feint_timer'] -= 1
        inputs &= ~INPUT_FORWARD
        inputs |= INPUT_BACKWARD
    elif obs['target_d2'] < 2500 and rng.random() < 0.006:
        st['feint_timer'] = rng.randint(6, 12)

    # Horn work when engaged — a randomly chosen move held a short while (not a
    # fixed cycle), frequency scaled by aggression.
    if obs['target_d2'] < 1600:
        if st['horn_timer'] > 0:
            st['horn_timer'] -= 1
            inputs |= st['horn']
        elif rng.random() < 0.05 * (0.5 + p['aggression']):
            st['horn'] = rng.choice((INPUT_HORN_UP, INPUT_HORN_DOWN,
                                     INPUT_HORN_LEFT, INPUT_HORN_RIGHT))
            st['horn_timer'] = rng.randint(8, 20)
    return inputs


# Host-authoritative input delays (frames at 60Hz).
# Host runs authoritative physics and applies its own input immediately.
# Guest predicts locally with zero delay too; raise GUEST_INPUT_DELAY_FRAMES
# to 2-3 if guest rubber-banding feels bad in testing (shrinks the window
# between local prediction and the host's authoritative result).
HOST_INPUT_DELAY_FRAMES = 0
GUEST_INPUT_DELAY_FRAMES = 0


class InputBuffer:
    """
    Input buffer for P2P networking.

    Host-authoritative mode (default): the simulation NEVER blocks waiting
    for the opponent. If the exact remote input for a frame hasn't arrived,
    the last-known remote input is used instead. The host's simulation is
    authoritative; the guest predicts locally and is corrected by state sync.

    Legacy lockstep mode (host_authoritative=False): won't simulate a frame
    until BOTH players' inputs exist for it, with a fixed symmetric delay.

    For local play, delay is 0 and can_simulate() is always True.
    """

    # Legacy lockstep delay - kept for reference / fallback mode
    NETWORK_INPUT_DELAY = 8

    # Storage slots (matches network MAX_PLAYERS; slots 2-3 used from Phase 4)
    NUM_SLOTS = 4

    def __init__(self, delay_frames=0):
        self.delay = delay_frames
        # Per-slot input streams: player_inputs[slot] = {frame: input_bits}
        self.player_inputs = {s: {} for s in range(self.NUM_SLOTS)}
        self.last_known = {s: 0 for s in range(self.NUM_SLOTS)}     # Newest bits per slot
        self.latest_frame = {s: -1 for s in range(self.NUM_SLOTS)}  # Newest frame per slot
        self.current_frame = 0    # The frame we're about to simulate
        self.is_network_mode = False  # Set True when connected to opponent
        self.local_player_id = 0  # Our slot (0 = host/blue, 1-3 = guests)

        # Host-authoritative mode: never block waiting for remote input.
        # Set False to restore legacy lockstep behavior.
        self.host_authoritative = True
        self.total_stale = 0        # Frames simulated reusing stale remote input

        # Lockstep state
        self.waiting_for_remote = False  # True when blocked waiting for opponent
        self.frames_waited = 0  # How many frames we've been waiting
        self.max_wait_frames = 180  # 3 seconds at 60fps before timeout

        # Network stats
        self.remote_frame_received = -1  # Highest frame number received from opponent
        self.frames_behind = 0  # How far behind opponent we are

        # Debug stats for network responsiveness analysis
        self.debug_wait_count = 0  # How many times we waited for opponent
        self.debug_predict_count = 0  # How many times we used input prediction
        self.debug_total_frames = 0  # Total frames processed
        self.debug_last_report = 0  # Last frame we printed debug info

        # Cumulative session counters for the net debug HUD
        # (debug_* counters above reset every ~2s for the periodic console report)
        self.total_waits = 0     # Total frames spent blocked on opponent input
        self.total_predicts = 0  # Total frames simulated with predicted/stale input

        # State sync (host sends authoritative state periodically)
        self.last_state_sync_frame = 0
        self.state_sync_interval = 30  # Every 30 frames (~500ms)

        # Jitter buffer for handling variable ping (professional netcode technique)
        self.ping_samples = []  # Last 60 ping samples for percentile calculation
        self.max_ping_samples = 60  # ~1 second of samples at 60Hz
        self.last_delay_recalc_time = 0.0  # Real time when we last recalculated delay
        self.delay_recalc_interval = 5.0  # Recalculate delay every 5 seconds

    def add_local(self, inputs):
        """Store local player's inputs for the current frame."""
        self.player_inputs[self.local_player_id][self.current_frame] = inputs
        self.last_known[self.local_player_id] = inputs
        if self.current_frame > self.latest_frame[self.local_player_id]:
            self.latest_frame[self.local_player_id] = self.current_frame

    def add_remote(self, slot, frame, inputs):
        """Store a remote player's inputs (received from network)."""
        self.player_inputs[slot][frame] = inputs

        # Track newest frame/bits per slot (last-known fallback)
        if frame > self.latest_frame[slot]:
            self.latest_frame[slot] = frame
            self.last_known[slot] = inputs
        # Aggregate "highest remote frame" for sync diagnostics
        if frame > self.remote_frame_received:
            self.remote_frame_received = frame

    def clear_remote_inputs(self):
        """Forget all remote input (e.g. on disconnect, to stop ghost beetles)."""
        for s in range(self.NUM_SLOTS):
            if s != self.local_player_id:
                self.player_inputs[s].clear()
                self.last_known[s] = 0
                self.latest_frame[s] = -1

    def get_sim_frame(self):
        """Get the frame number we should be simulating (current - delay)."""
        return max(0, self.current_frame - self.delay)

    def can_simulate(self):
        """
        Check if we can simulate the next physics frame.

        Host-authoritative mode: ALWAYS True - missing remote input falls
        back to last-known input in get_frame_inputs(). No freezes, ever.
        Legacy lockstep mode: requires BOTH players' inputs for the frame.
        """
        if not self.is_network_mode:
            return True  # Local mode: always can simulate

        if self.host_authoritative:
            self.waiting_for_remote = False
            self.frames_waited = 0
            self.debug_total_frames += 1
            return True

        # Legacy 2P lockstep path (host_authoritative=False fallback only)
        sim_frame = self.get_sim_frame()
        local_slot = self.local_player_id
        remote_slot = 1 - local_slot
        local_stream = self.player_inputs[local_slot]
        remote_stream = self.player_inputs[remote_slot]

        # Check if we have local input for this frame
        has_local = sim_frame in local_stream

        # Check if we have remote input for this frame
        # Due to UDP packet loss, we might be missing exact frames
        # If we have a newer frame, use that instead (input prediction)
        has_remote = sim_frame in remote_stream
        used_prediction = False
        if not has_remote and self.latest_frame[remote_slot] >= sim_frame:
            # We have newer inputs - find the closest one and use it
            for f in range(sim_frame, self.latest_frame[remote_slot] + 1):
                if f in remote_stream:
                    # Copy this input to the missing frame (assume same input)
                    remote_stream[sim_frame] = remote_stream[f]
                    has_remote = True
                    used_prediction = True
                    self.debug_predict_count += 1
                    self.total_predicts += 1
                    break

        if has_local and has_remote:
            self.waiting_for_remote = False
            self.frames_waited = 0
            self.debug_total_frames += 1
            return True
        else:
            if not has_remote:
                self.waiting_for_remote = True
                self.frames_waited += 1
                self.debug_wait_count += 1
                self.total_waits += 1
            return False

    def get_input_for(self, slot, frame):
        """Input bits for one slot at one frame: exact if present, else the
        newest received (host-authoritative last-known fallback)."""
        stream = self.player_inputs[slot]
        if frame in stream:
            return stream[frame]
        if slot != self.local_player_id and self.is_network_mode:
            self.total_stale += 1
        return self.last_known[slot]

    def get_frame_inputs(self, frame, count=2):
        """
        Get inputs for a physics frame.

        Returns: list of input bits indexed by player slot, length `count`.
        """
        target = frame - self.delay if not self.is_network_mode else self.get_sim_frame()
        target = max(0, target)
        return [self.get_input_for(slot, target) for slot in range(count)]

    def has_inputs_for_frame(self, frame):
        """Check if we can process a frame (legacy lockstep helper)."""
        if not self.is_network_mode:
            return True
        return self.can_simulate()

    def advance_frame(self):
        """Move to next frame."""
        self.current_frame += 1

        # Cleanup old inputs (keep last 120 frames = 2 seconds)
        cleanup_threshold = self.current_frame - 120
        for stream in self.player_inputs.values():
            for k in [k for k in stream if k <= cleanup_threshold]:
                del stream[k]

    def _get_percentile_ping(self, percentile=90):
        """Get the Nth percentile ping from samples (jitter buffer technique).

        Using 90th percentile instead of average accounts for ping spikes,
        preventing input drops during momentary latency increases.
        """
        if not self.ping_samples:
            return 60  # Default if no samples yet

        sorted_samples = sorted(self.ping_samples)
        index = int(len(sorted_samples) * percentile / 100)
        index = min(index, len(sorted_samples) - 1)
        return sorted_samples[index]

    def set_network_delay(self, ping_ms):
        """Set input delay based on measured network latency.

        Called at match start to set initial delay.
        """
        # Add to samples for jitter buffer
        self.ping_samples.append(ping_ms)
        if len(self.ping_samples) > self.max_ping_samples:
            self.ping_samples.pop(0)

        # Convert ping to frames: delay = (ping/2) / 16.67ms per frame
        # Add 1 frame safety margin
        one_way_ms = ping_ms / 2.0
        delay_frames = int(one_way_ms / 16.67) + 1
        # Clamp between 2 and 8 frames (higher max handles up to ~250ms ping)
        self.delay = max(2, min(8, delay_frames))
        self.last_delay_recalc_time = time.time()
        print(f"[InputBuffer] Set delay to {self.delay} frames for {ping_ms:.0f}ms ping")

    def update_ping_sample(self, ping_ms):
        """Add ping sample and periodically recalculate delay.

        Call this every frame during online play with current ping.
        Uses jitter buffer (90th percentile) for stable delay calculation.
        Limits delay changes to ±1 frame to prevent jarring shifts.
        """
        # Add sample to rolling buffer
        self.ping_samples.append(ping_ms)
        if len(self.ping_samples) > self.max_ping_samples:
            self.ping_samples.pop(0)

        # Check if it's time to recalculate delay
        current_time = time.time()
        if current_time - self.last_delay_recalc_time < self.delay_recalc_interval:
            return  # Not time yet

        self.last_delay_recalc_time = current_time

        # Use 90th percentile to handle ping spikes
        percentile_ping = self._get_percentile_ping(90)

        # Calculate target delay
        one_way_ms = percentile_ping / 2.0
        target_delay = int(one_way_ms / 16.67) + 1
        target_delay = max(2, min(8, target_delay))

        # Limit change to ±1 frame per recalculation to prevent jarring shifts
        if target_delay > self.delay:
            new_delay = min(self.delay + 1, target_delay)
        elif target_delay < self.delay:
            new_delay = max(self.delay - 1, target_delay)
        else:
            new_delay = self.delay

        if new_delay != self.delay:
            print(f"[InputBuffer] Adjusted delay: {self.delay} -> {new_delay} frames (90th percentile ping: {percentile_ping:.0f}ms)")
            self.delay = new_delay

    def reset(self):
        """Reset buffer for new match."""
        for s in range(self.NUM_SLOTS):
            self.player_inputs[s].clear()
            self.last_known[s] = 0
            self.latest_frame[s] = -1
        self.current_frame = 0
        self.waiting_for_remote = False
        self.frames_waited = 0
        self.remote_frame_received = -1
        self.frames_behind = 0
        self.last_state_sync_frame = 0
        self.total_stale = 0
        self.total_waits = 0
        self.total_predicts = 0
        # Reset jitter buffer state for fresh match
        self.ping_samples.clear()
        self.last_delay_recalc_time = time.time()


# Global input buffer instance (used by main loop)
input_buffer = InputBuffer(delay_frames=0)  # 0 delay for local play

# ============================================================================
# NETWORK STATE (for online play)
# ============================================================================
network_manager = None          # NetworkManager instance (created when hosting/joining)
game_state = GAME_STATE_TITLE   # Start at title screen
local_player_id = 0             # 0 = blue/host, 1 = red/guest
title_transition_timer = 0.0    # Timer for title-to-game camera transition
arena_lights_timer = 0.0        # Timer for dramatic arena lights turn-on effect
ARENA_LIGHTS_FADEIN = 0.8       # Duration for lights to fade in (seconds)
lobby_id_input = ""             # Text input for joining lobby by ID
network_error_msg = ""          # Error message to display

def cleanup_network():
    """Clean up network resources on exit to prevent orphaned Steam sockets."""
    global network_manager
    if network_manager is not None:
        print("[Network] Cleaning up on exit...")
        try:
            # Send disconnect message to peer if connected
            if network_manager.connected:
                network_manager.send_disconnect()
            network_manager.shutdown()
        except Exception as e:
            print(f"[Network] Cleanup error (ignorable): {e}")
        network_manager = None
        print("[Network] Cleanup complete")

# Register cleanup to run on exit (prevents orphaned Steam sockets)
atexit.register(cleanup_network)

# Edge tipping constants
EDGE_TIPPING_STRENGTH = 0.45  # Force multiplier per over-edge voxel
ARENA_CENTER_X = 64.0  # Arena center X coordinate
ARENA_CENTER_Z = 64.0  # Arena center Z coordinate
ARENA_EDGE_RADIUS = 30.0  # Arena edge radius (voxels beyond this trigger tipping)

# Fixed timestep physics constants
PHYSICS_TIMESTEP = 1.0 / 60.0  # 60 Hz physics update rate (16.67ms per step)
MAX_TIMESTEP_ACCUMULATOR = 0.25  # Max accumulator to prevent spiral of death

# Horn rotation damping constants (Phase 2: Horn Clipping Prevention)
HORN_DAMPING_INTO = 0.80      # Damping when rotating into collision (0.80 = 20% speed, high resistance when pushing into collision)
HORN_DAMPING_AWAY = 0.15      # Damping when rotating away from collision (0.15 = 85% speed)
HORN_DAMPING_NEUTRAL = 0.30   # Damping when not actively rotating
