SPAWN_RING_DIST_RESPAWN = 8.0    # Respawn: near center but not stacked on it

def get_spawn_position(slot=0, is_initial=False, for_blue=None, player_count=None):
    """Get a valid spawn position for a player slot based on current arena mode.
    Returns (x, z, rotation) tuple - rotation faces the arena center.
    is_initial=True for game start positions, False for respawns.

    Slots 0/1 keep the exact historical blue/red positions per arena mode.
    Slots 2+ spawn on an evenly-spaced ring facing center - proportional, so
    it stays inside every arena; per-arena tuning can be layered on later.
    (for_blue kept for backward compatibility: True->slot 0, False->slot 1.)
    """
    import random

    if for_blue is not None:
        slot = 0 if for_blue else 1
    if player_count is None:
        player_count = active_player_count

    if slot >= 2:
        # Players 3/4: ring spawn facing center. Slot 0 is west and slot 1
        # east historically; evenly spacing from west keeps that pattern
        # (4P: slot 2 = north, slot 3 = south).
        angle = math.pi + slot * (2.0 * math.pi / max(2, player_count))
        dist = SPAWN_RING_DIST_INITIAL if is_initial else SPAWN_RING_DIST_RESPAWN
        x = math.cos(angle) * dist
        z = math.sin(angle) * dist
        rotation = (angle + math.pi) % (2.0 * math.pi)  # Face inward
        return (x, z, rotation)

    for_blue = (slot == 0)

    if donut_mode:
        # Spawn on the donut ring - pick random angle and distance
        angle = random.uniform(0, 2 * math.pi)
        # Spawn in middle of the ring (between inner and outer radius)
        spawn_radius = (DONUT_INNER_RADIUS + DONUT_OUTER_RADIUS) / 2
        x = math.cos(angle) * spawn_radius
        z = math.sin(angle) * spawn_radius
        # Face toward center (or opposite beetle)
        rotation = angle + math.pi  # Face inward
        return (x, z, rotation)
    elif barbell_mode:
        # Spawn at center of respective circle, facing the other circle
        if for_blue:
            return (BARBELL_LEFT_CENTER_X, 0.0, 0.0)  # Left circle, face right
        else:
            return (BARBELL_RIGHT_CENTER_X, 0.0, math.pi)  # Right circle, face left
    elif figure8_mode:
        # Spawn on tips (outermost points of each loop)
        if for_blue:
            return (-36.0, 0.0, 0.0)   # Left tip of left loop, face right
        else:
            return (36.0, 0.0, math.pi) # Right tip of right loop, face left
    elif yinyang_mode:
        # Spawn on opposite sides of the ring
        ring_spawn_radius = (YINYANG_INNER_RADIUS + YINYANG_OUTER_RADIUS) / 2  # Middle of ring
        if for_blue:
            return (-ring_spawn_radius, 0.0, 0.0)  # West side, face right
        else:
            return (ring_spawn_radius, 0.0, math.pi)  # East side, face left
    elif hourglass_mode:
        # Spawn at the meatiest part of the hourglass (not too close to edge)
        spawn_x = 18.0  # About 56% out - good width here
        if for_blue:
            return (-spawn_x, 0.0, 0.0)  # Left side, face right
        else:
            return (spawn_x, 0.0, math.pi)  # Right side, face left
    elif square_bridge_mode:
        # Spawn on opposite ends of the long bridge, facing each other
        spawn_x = 20.0  # On the bridge, toward each end
        if for_blue:
            return (-spawn_x, 0.0, 0.0)  # Left end of bridge, face right
        else:
            return (spawn_x, 0.0, math.pi)  # Right end of bridge, face left
    elif square_mode:
        # Spawn at center of the square platform, facing each other
        if for_blue:
            return (0.0, 0.0, 0.0)  # Center, face right
        else:
            return (0.0, 0.0, math.pi)  # Center, face left
    elif cut_square_mode:
        # Spawn on the diagonal bridge, offset from center (which is over the hole)
        spawn_off = 10.0  # Along the dx=dz diagonal
        if for_blue:
            return (-spawn_off, -spawn_off, math.pi / 4)  # Bottom-left of bridge, face along diagonal
        else:
            return (spawn_off, spawn_off, math.pi + math.pi / 4)  # Top-right of bridge, face along diagonal
    elif squiggle_mode:
        # Spawn on opposite ends of the serpentine (leftmost and rightmost segments)
        if for_blue:
            return (-SQUIGGLE_SPAWN_X, 0.0, 0.0)  # Left end, face right
        else:
            return (SQUIGGLE_SPAWN_X, 0.0, math.pi)  # Right end, face left
    elif star_mode:
        # Spawn in center like default circle arena
        if is_initial:
            if for_blue:
                return (-20.0, 0.0, 0.0)
            else:
                return (20.0, 0.0, math.pi)
        else:
            if for_blue:
                return (0.0, 0.0, 0.0)
            else:
                return (0.0, 0.0, math.pi)
    else:
        # Normal arena
        if is_initial:
            # Initial game start positions (spread apart)
            if for_blue:
                return (-20.0, 0.0, 0.0)  # Blue on left, facing right
            else:
                return (20.0, 0.0, math.pi)  # Red on right, facing left
        else:
            # Respawn at center
            if for_blue:
                return (0.0, 0.0, 0.0)  # Center, facing right
            else:
                return (0.0, 0.0, math.pi)  # Center, facing left

