@ti.kernel
def spawn_tornado_dust(pos_x: ti.f32, pos_z: ti.f32, time_val: ti.f32):
    """Spawn swirling funnel particles on the funnel wall surface.
    Tight at base, wider at top — particles hug the shell for a defined shape."""
    floor_y = 33.5  # RENDER_Y_OFFSET + 0.5 (arena surface)
    height = 35.0   # TORNADO_HEIGHT

    for i in range(35):  # TORNADO_DUST_COUNT
        idx = ti.atomic_add(simulation.num_debris[None], 1)
        if idx < simulation.MAX_DEBRIS:
            simulation.debris_active[idx] = 1
            ti.atomic_add(simulation.debris_active_count[None], 1)
            # Top-biased height: sqrt pushes more particles toward top to compensate for shorter lifetime there
            h_frac = ti.sqrt(ti.random())
            spawn_y = floor_y + h_frac * height
            # Funnel wall radius: tight base (1.0), wide top (10.0)
            wall_radius = 1.0 + h_frac * h_frac * 9.0  # Quadratic flare
            shell_jitter = wall_radius * 0.1 * (ti.random() - 0.5)  # Thin crisp wall
            radius = wall_radius + shell_jitter
            # 3 spiral arms that rotate with time — visible spin like a galaxy
            arm = ti.cast(ti.floor(ti.random() * 3.0), ti.i32)  # Pick arm 0, 1, or 2
            arm_base = ti.cast(arm, ti.f32) * 2.094  # 120° apart (2*pi/3)
            # Each arm twists up the funnel + rotates with time
            angle = arm_base + time_val * 21.0 + h_frac * 3.0 + (ti.random() - 0.5) * 0.7
            spawn_x = pos_x + ti.cos(angle) * radius
            spawn_z = pos_z + ti.sin(angle) * radius
            simulation.debris_pos[idx] = ti.math.vec3(spawn_x, spawn_y, spawn_z)
            # Velocity: tangential swirl + inward pull to stay on funnel + gentle updraft
            swirl_speed = 33.0 * (0.4 + h_frac * 0.6)  # Horizontal spin
            inward = -6.0 - h_frac * 10.0  # Pull toward center (stronger at top where radius is wider)
            vx = -ti.sin(angle) * swirl_speed + ti.cos(angle) * inward
            vz = ti.cos(angle) * swirl_speed + ti.sin(angle) * inward
            vy = 1.5 + h_frac * 3.0  # Gentle updraft
            simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)
            # Dark stormy color from palette + variation
            color_idx = ti.cast(ti.random() * 3.0, ti.i32) % 3
            cr = 0.0
            cg = 0.0
            cb = 0.0
            if color_idx == 0:
                cr, cg, cb = 0.35, 0.33, 0.31
            elif color_idx == 1:
                cr, cg, cb = 0.40, 0.29, 0.22
            else:
                cr, cg, cb = 0.45, 0.43, 0.40
            cr += (ti.random() - 0.5) * 0.10
            cg += (ti.random() - 0.5) * 0.08
            cb += (ti.random() - 0.5) * 0.08
            simulation.debris_material[idx] = ti.math.vec3(cr, cg, cb)
            # Shorter lifetime at top (wide part) so particles die before drifting off the funnel
            simulation.debris_lifetime[idx] = (0.35 + ti.random() * 0.25) * (1.0 - h_frac * 0.6)  # base 0.35-0.6s, top 40% of that

@ti.kernel
def spawn_tornado_ground_dust(pos_x: ti.f32, pos_z: ti.f32, time_val: ti.f32, spawn_y: ti.f32):
    """Spawn radial dust spray where tornado base meets solid arena floor.
    Floor height pre-checked on CPU and passed as spawn_y (-1 = no floor)."""
    if spawn_y > 0.0:
        for i in range(8):
                idx = ti.atomic_add(simulation.num_debris[None], 1)
                if idx < simulation.MAX_DEBRIS:
                    simulation.debris_active[idx] = 1
                    ti.atomic_add(simulation.debris_active_count[None], 1)
                    # Radial burst outward from tornado base
                    angle = ti.random() * 6.283
                    speed = 8.0 + ti.random() * 12.0
                    # Spawn at base with slight random offset
                    off_r = ti.random() * 2.0
                    simulation.debris_pos[idx] = ti.math.vec3(
                        pos_x + ti.cos(angle) * off_r,
                        spawn_y + ti.random() * 1.5,
                        pos_z + ti.sin(angle) * off_r
                    )
                    simulation.debris_vel[idx] = ti.math.vec3(
                        ti.cos(angle) * speed + (ti.random() - 0.5) * 4.0,
                        1.0 + ti.random() * 3.0,
                        ti.sin(angle) * speed + (ti.random() - 0.5) * 4.0
                    )
                    # Dusty brown/tan tones
                    cr = 0.55 + ti.random() * 0.15
                    cg = 0.45 + ti.random() * 0.12
                    cb = 0.30 + ti.random() * 0.10
                    simulation.debris_material[idx] = ti.math.vec3(cr, cg, cb)
                    simulation.debris_radius[idx] = 0.20
                    simulation.debris_lifetime[idx] = 0.3 + ti.random() * 0.3

@ti.kernel
def spawn_sandstorm_dust(wind_dx: ti.f32, wind_dz: ti.f32, intensity: ti.f32, time_val: ti.f32, count: ti.i32):
    """Fast chaotic sand blasting through the arena, count pre-computed on CPU."""
    floor_y = 33.5  # RENDER_Y_OFFSET + 0.5 (arena surface)

    for i in range(count):
        idx = ti.atomic_add(simulation.num_debris[None], 1)
        if idx < simulation.MAX_DEBRIS:
            simulation.debris_active[idx] = 1
            ti.atomic_add(simulation.debris_active_count[None], 1)
            # Mix of close and far spawns — close ones for responsiveness,
            # far ones so you can see the storm coming from a distance
            perp_x = -wind_dz
            perp_z = wind_dx
            spawn_dist = 60.0 + ti.random() * 140.0  # 60-200 units upwind
            spread = (ti.random() - 0.5) * 85.0  # Perpendicular spread
            spawn_x = -wind_dx * spawn_dist + perp_x * spread
            spawn_z = -wind_dz * spawn_dist + perp_z * spread
            # Spawn above arena surface — most low, some higher for visual depth
            r = ti.random()
            spawn_y = floor_y + 2.0 + r * 6.0 + r * r * 8.0
            simulation.debris_pos[idx] = ti.math.vec3(spawn_x, spawn_y, spawn_z)
            # Speed scales hard with intensity: visible breeze → ripping blast
            spd = (80.0 + intensity * 270.0) + ti.random() * 60.0  # 80-410 units/s, more speed variation
            # Wider lateral spread for chaotic stormy feel
            dir_spread = (ti.random() - 0.5) * 0.35
            vx = (wind_dx + perp_x * dir_spread) * spd
            vz = (wind_dz + perp_z * dir_spread) * spd
            # Turbulent vertical — some particles dip, some surge up
            vy = (ti.random() - 0.3) * 8.0 + spawn_dist * 0.06 + 3.0
            simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)
            # Sandy color — tight palette for cohesive look
            color_idx = ti.cast(ti.random() * 4.0, ti.i32) % 4
            cr = 0.0
            cg = 0.0
            cb = 0.0
            if color_idx == 0:
                cr, cg, cb = 0.85, 0.72, 0.28  # Warm sand
            elif color_idx == 1:
                cr, cg, cb = 0.75, 0.60, 0.22  # Golden
            elif color_idx == 2:
                cr, cg, cb = 0.60, 0.48, 0.20  # Dusty brown
            else:
                cr, cg, cb = 0.50, 0.38, 0.18  # Dark sand
            # Subtle variation
            cr += (ti.random() - 0.5) * 0.06
            cg += (ti.random() - 0.5) * 0.05
            cb += (ti.random() - 0.5) * 0.03
            simulation.debris_material[idx] = ti.math.vec3(cr, cg, cb)
            # Sand grain size
            simulation.debris_radius[idx] = 0.18 + ti.random() * 0.08  # Bigger, varied streaks
            # Lifetime scales with spawn distance — far particles live longer to make the trip,
            # close ones die fast so screen clears quickly when gust ends.
            # spawn_dist/spd = travel time to arena. Add margin to cross arena + blow out the other side.
            simulation.debris_lifetime[idx] = spawn_dist / spd + 1.2 + ti.random() * 0.4

@ti.kernel
def spawn_ball_bounce_dust(pos_x: ti.f32, pos_y: ti.f32, pos_z: ti.f32,
                           impact_speed: ti.f32, ball_radius: ti.f32):
    """Spawn radial dust ring when ball bounces - more particles for harder impacts"""
    # Scale particle count with impact - fewer at min, more dramatic at high speeds
    # At threshold (7.0): 2 particles, at high speed (15+): ~20 particles
    scaled_speed = ti.max(0.0, impact_speed - 7.0)  # Subtract threshold
    num_particles = 2 + ti.cast(scaled_speed * 2.0, ti.i32)
    num_particles = ti.min(num_particles, 22)  # Cap at 22

    # Dust color (same brownish-gray as leg dust)
    color_r = 0.45
    color_g = 0.40
    color_b = 0.35

    # Impact intensity factor (0.0 at threshold, 1.0 at strong hit)
    intensity = ti.min(scaled_speed / 20.0, 1.0)  # 0-1 range over impact 7-27
    # Speed scales with impact (harder hit = faster dust)
    base_speed = 1.0 + intensity * 10.0
    upward_ratio = 0.3 + intensity * 0.4  # Low bounces stay flat, big bounces splash up

    # Fixed loop with conditional (Taichi needs compile-time loop bounds)
    for i in range(32):
        if i < num_particles:
            idx = ti.atomic_add(simulation.num_debris[None], 1)
            if idx < simulation.MAX_DEBRIS:
                simulation.debris_active[idx] = 1  # Mark slot as active (free list pattern)
                ti.atomic_add(simulation.debris_active_count[None], 1)  # Track live count
                # Loosely spaced angles — evenly distributed but with natural jitter
                angle = (float(i) / float(num_particles)) * 2.0 * 3.14159 + (ti.random() - 0.5) * 0.5

                # Spawn at ball edge with slight radial scatter
                spawn_radius = ball_radius * (0.7 + ti.random() * 0.3)
                spawn_x = pos_x + ti.cos(angle) * spawn_radius
                spawn_z = pos_z + ti.sin(angle) * spawn_radius

                simulation.debris_pos[idx] = ti.math.vec3(spawn_x, pos_y + 0.5, spawn_z)

                # Velocity points outward — moderate variation in speed
                particle_speed = base_speed * (0.8 + ti.random() * 0.4)
                vx = ti.cos(angle) * particle_speed
                vz = ti.sin(angle) * particle_speed
                vy = particle_speed * upward_ratio * (0.7 + ti.random() * 0.6)

                simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)

                # Dust color with slight variation
                color_var = 0.9 + ti.random() * 0.2
                simulation.debris_material[idx] = ti.math.vec3(color_r * color_var, color_g * color_var, color_b * color_var)

                # Lifetime scales slightly with impact (bigger bounce = longer hang time)
                simulation.debris_lifetime[idx] = 0.2 + intensity * 0.5 + ti.random() * 0.1

@ti.kernel
def spawn_ball_roll_dust(pos_x: ti.f32, pos_y: ti.f32, pos_z: ti.f32,
                         speed: ti.f32, ball_radius: ti.f32):
    """Spawn dust trail behind rolling ball"""
    # Spawn 2-3 particles per call for visible trail
    num = 2 + ti.cast(ti.random() * 2.0, ti.i32)  # 2 or 3
    for i in range(3):
        if i < num:
            idx = ti.atomic_add(simulation.num_debris[None], 1)
            if idx < simulation.MAX_DEBRIS:
                simulation.debris_active[idx] = 1
                ti.atomic_add(simulation.debris_active_count[None], 1)

                # Spawn at ground contact with random offset
                offset_angle = ti.random() * 2.0 * 3.14159
                offset_r = ball_radius * 0.5 * ti.random()
                spawn_x = pos_x + ti.cos(offset_angle) * offset_r
                spawn_z = pos_z + ti.sin(offset_angle) * offset_r

                simulation.debris_pos[idx] = ti.math.vec3(spawn_x, pos_y + 0.3, spawn_z)

                # Upward drift with horizontal scatter
                vx = (ti.random() - 0.5) * 2.0
                vz = (ti.random() - 0.5) * 2.0
                vy = 1.0 + ti.random() * 2.0

                simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)

                # Brownish dust color
                color_var = 0.9 + ti.random() * 0.2
                simulation.debris_material[idx] = ti.math.vec3(0.45 * color_var, 0.40 * color_var, 0.35 * color_var)

                # Longer lifetime for visibility
                simulation.debris_lifetime[idx] = 0.3 + ti.random() * 0.3

@ti.kernel
def spawn_arena_transition_ring(ring_radius: ti.f32, ring_width: ti.f32, num_particles: ti.i32):
    """Spawn debris particles in a ring pattern for arena transition effect.
    Deterministic based on ring_radius for network sync."""
    # Use board color with brightness boost for better visibility
    board_col = simulation.board_color[None]
    color_r = board_col[0] * 1.3
    color_g = board_col[1] * 1.3
    color_b = board_col[2] * 1.3

    for i in range(num_particles):
        # Deterministic angle based on particle index
        angle = ti.cast(i, ti.f32) * 6.28318 / ti.cast(num_particles, ti.f32)

        # Position on ring with slight random offset
        r = ring_radius + (ti.random() - 0.5) * ring_width
        pos_x = ti.cos(angle) * r
        pos_z = ti.sin(angle) * r
        pos_y = RENDER_Y_OFFSET + 0.5  # Just above floor

        # Outward + upward velocity
        outward_speed = 15.0 + ti.random() * 10.0
        upward_speed = 20.0 + ti.random() * 15.0
        vx = ti.cos(angle) * outward_speed
        vz = ti.sin(angle) * outward_speed
        vy = upward_speed

        idx = ti.atomic_add(simulation.num_debris[None], 1)
        if idx < simulation.MAX_DEBRIS:
            simulation.debris_active[idx] = 1
            ti.atomic_add(simulation.debris_active_count[None], 1)
            simulation.debris_pos[idx] = ti.math.vec3(pos_x, pos_y, pos_z)
            simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)
            # Color variation
            color_var = 0.85 + ti.random() * 0.3
            simulation.debris_material[idx] = ti.math.vec3(color_r * color_var, color_g * color_var, color_b * color_var)
            simulation.debris_lifetime[idx] = 0.6 + ti.random() * 0.3

def start_arena_transition():
    """Queue arena transition to start at beginning of next frame (before rendering)."""
    global arena_transition_pending
    arena_transition_pending = True

def process_pending_arena_transition():
    """Called at frame start (before rendering) to spawn first ring immediately."""
    global arena_transition_pending, arena_transition_active, arena_transition_timer, arena_transition_radius
    if arena_transition_pending:
        arena_transition_pending = False
        arena_transition_active = True
        arena_transition_timer = 0.0
        arena_transition_radius = 4.0
        # Spawn first ring immediately - will be visible this frame
        spawn_arena_transition_ring(4.0, 4.0, 12)

@ti.kernel
def spawn_arena_transition_rings(start_radius: ti.f32, ring_spacing: ti.f32, num_rings: ti.i32):
    """Spawn all pending transition rings in a single kernel launch.
    Flat loop over num_rings * 60 slots; each thread computes its ring and angle."""
    board_col = simulation.board_color[None]
    color_r = board_col[0] * 1.3
    color_g = board_col[1] * 1.3
    color_b = board_col[2] * 1.3

    for flat_idx in range(num_rings * 60):
        ring_idx = flat_idx // 60
        particle_idx = flat_idx % 60

        ring_radius = start_radius + ti.cast(ring_idx, ti.f32) * ring_spacing
        num_particles = ti.cast(ti.max(12.0, ti.min(ring_radius * 2.0, 60.0)), ti.i32)

        if particle_idx < num_particles:
            angle = ti.cast(particle_idx, ti.f32) * 6.28318 / ti.cast(num_particles, ti.f32)

            r = ring_radius + (ti.random() - 0.5) * ring_spacing
            pos_x = ti.cos(angle) * r
            pos_z = ti.sin(angle) * r
            pos_y = RENDER_Y_OFFSET + 0.5

            outward_speed = 15.0 + ti.random() * 10.0
            upward_speed = 20.0 + ti.random() * 15.0
            vx = ti.cos(angle) * outward_speed
            vz = ti.sin(angle) * outward_speed
            vy = upward_speed

            idx = ti.atomic_add(simulation.num_debris[None], 1)
            if idx < simulation.MAX_DEBRIS:
                simulation.debris_active[idx] = 1
                ti.atomic_add(simulation.debris_active_count[None], 1)
                simulation.debris_pos[idx] = ti.math.vec3(pos_x, pos_y, pos_z)
                simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)
                color_var = 0.85 + ti.random() * 0.3
                simulation.debris_material[idx] = ti.math.vec3(color_r * color_var, color_g * color_var, color_b * color_var)
                simulation.debris_lifetime[idx] = 0.6 + ti.random() * 0.3

def update_arena_transition(dt):
    """Update arena transition effect - spawn debris rings expanding outward."""
    global arena_transition_active, arena_transition_timer, arena_transition_radius

    if not arena_transition_active:
        return

    arena_transition_timer += dt

    # Calculate target radius based on time
    progress = arena_transition_timer / ARENA_TRANSITION_DURATION
    target_radius = progress * ARENA_TRANSITION_MAX_RADIUS

    # Count rings to spawn, then batch into single kernel launch
    ring_spacing = 4.0
    num_rings = 0
    start_radius = arena_transition_radius + ring_spacing
    while arena_transition_radius + ring_spacing < target_radius:
        arena_transition_radius += ring_spacing
        num_rings += 1

    if num_rings > 0:
        spawn_arena_transition_rings(start_radius, ring_spacing, num_rings)

    # End transition when complete
    if progress >= 1.0:
        arena_transition_active = False

def update_pending_arena_switch(dt):
    """Update delayed arena switch - counts down timer and executes switch."""
    global pending_arena_switch, donut_mode, x_stage_mode, barbell_mode, figure8_mode, yinyang_mode, hourglass_mode, square_bridge_mode, square_mode, squiggle_mode

    if pending_arena_switch is None:
        return

    mode_name, delay_remaining = pending_arena_switch
    delay_remaining -= dt

    if delay_remaining <= 0:
        # Execute the arena switch now
        pending_arena_switch = None

        if mode_name == 'normal':
            simulation.init_beetle_arena()
            renderer.set_arena_snap(1)
        elif mode_name == 'donut':
            simulation.init_donut_arena()
            renderer.set_arena_snap(2)
        elif mode_name == 'x_stage':
            simulation.init_x_stage_arena()
            renderer.set_arena_snap(3)
        elif mode_name == 'barbell':
            simulation.init_barbell_arena()
            renderer.set_arena_snap(4)
        elif mode_name == 'figure8':
            simulation.init_figure8_arena()
            renderer.set_arena_snap(9)
        elif mode_name == 'yinyang':
            simulation.init_yinyang_arena()
            renderer.set_arena_snap(5)
        elif mode_name == 'hourglass':
            simulation.init_hourglass_arena()
            renderer.set_arena_snap(6)
        elif mode_name == 'square_bridge':
            simulation.init_square_bridge_arena()
            renderer.set_arena_snap(7)
        elif mode_name == 'square':
            simulation.init_square_arena()
            renderer.set_arena_snap(11)
        elif mode_name == 'cut_square':
            simulation.init_cut_square_arena()
            renderer.set_arena_snap(11)
        elif mode_name == 'squiggle':
            simulation.init_squiggle_arena()
            renderer.set_arena_snap(10)
        elif mode_name == 'star':
            simulation.init_star_arena()
            renderer.set_arena_snap(12)
        elif mode_name == 'ball':
            simulation.init_beetle_arena()
            renderer.set_arena_snap(8)
        elif mode_name == 'ball_off':
            # Restore appropriate arena when ball mode turns off
            if donut_mode:
                simulation.init_donut_arena()
                renderer.set_arena_snap(2)
            elif x_stage_mode:
                simulation.init_x_stage_arena()
                renderer.set_arena_snap(3)
            elif barbell_mode:
                simulation.init_barbell_arena()
                renderer.set_arena_snap(4)
            elif figure8_mode:
                simulation.init_figure8_arena()
                renderer.set_arena_snap(9)
            elif yinyang_mode:
                simulation.init_yinyang_arena()
                renderer.set_arena_snap(5)
            elif hourglass_mode:
                simulation.init_hourglass_arena()
                renderer.set_arena_snap(6)
            elif square_bridge_mode:
                simulation.init_square_bridge_arena()
                renderer.set_arena_snap(7)
            elif square_mode:
                simulation.init_square_arena()
                renderer.set_arena_snap(11)
            elif cut_square_mode:
                simulation.init_cut_square_arena()
                renderer.set_arena_snap(11)
            elif squiggle_mode:
                simulation.init_squiggle_arena()
                renderer.set_arena_snap(10)
            elif star_mode:
                simulation.init_star_arena()
                renderer.set_arena_snap(12)
            else:
                simulation.init_beetle_arena()
                renderer.set_arena_snap(1)

        # Re-render bowl perimeter if ball is active (arena rebuild wipes it)
        if beetle_ball.active:
            simulation.render_bowl_perimeter()
            simulation.clear_goal_pit_floor()
        build_floor_height_cache()
    else:
        # Still waiting
        pending_arena_switch = (mode_name, delay_remaining)

def queue_arena_switch(mode_name):
    """Queue an arena switch with delay. Animation starts immediately."""
    global pending_arena_switch
    start_arena_transition()  # Start animation immediately
    pending_arena_switch = (mode_name, ARENA_SWITCH_DELAY)

def set_network_ball_mode(active):
    """
    Guest applies the host's ball mode with the SAME full setup the host does
    locally (ball init + queue_arena_switch, which rebuilds the arena, sets
    the arena snap, renders the bowl rim, and refreshes the floor cache).

    Called from BOTH the MSG_GAME_OPTIONS handler and the state-sync fallback;
    whichever arrives first wins, the other sees no change and returns.
    """
    global ball_cache_initialized
    if active == beetle_ball.active:
        return
    if active:
        if not ball_cache_initialized:
            init_ball_cache(beetle_ball.radius)
            ball_cache_initialized = True
        beetle_ball.x = 0.0
        beetle_ball.y = 28.0
        beetle_ball.z = 0.0
        beetle_ball.vx = 0.0
        beetle_ball.vy = 0.0
        beetle_ball.vz = 0.0
        beetle_ball.rotation = 0.0
        beetle_ball.angular_velocity = 0.0
        beetle_ball.pitch = 0.0
        beetle_ball.pitch_velocity = 0.0
        beetle_ball.roll = 0.0
        beetle_ball.roll_velocity = 0.0
        beetle_ball.prev_x = beetle_ball.x
        beetle_ball.prev_y = beetle_ball.y
        beetle_ball.prev_z = beetle_ball.z
        beetle_ball.prev_rotation = beetle_ball.rotation
        beetle_ball.prev_pitch = beetle_ball.pitch
        beetle_ball.prev_roll = beetle_ball.roll
        scores[0] = 0
        scores[1] = 0
        g['blue_score'] = 0
        g['red_score'] = 0
        g['ball_scored_this_fall'] = False
        g['ball_has_exploded'] = False
        g['ball_explosion_delay'] = 0.0
        g['ball_explosion_timer'] = 0.0
        beetle_ball.active = True
        queue_arena_switch('ball')
        print("Ball mode ON (from host)")
    else:
        if ball_last_rendered[None] == 1:
            num_voxels = ball_cache_size[None]
            if num_voxels > 0:
                clear_ball_fast(ball_last_grid_x[None], ball_last_grid_y[None], ball_last_grid_z[None], num_voxels)
            ball_last_rendered[None] = 0
        else:
            clear_ball()
        simulation.clear_bowl_perimeter()
        beetle_ball.active = False
        scores[0] = 0
        scores[1] = 0
        g['blue_score'] = 0
        g['red_score'] = 0
        queue_arena_switch('ball_off')
        print("Ball mode OFF (from host)")

