ufo_cache_y = ti.field(ti.i32, shape=MAX_UFO_VOXELS)
ufo_cache_z = ti.field(ti.i32, shape=MAX_UFO_VOXELS)
ufo_cache_type = ti.field(ti.i32, shape=MAX_UFO_VOXELS)

