def apply_comet_knockback(impact_x, impact_z, radius, force_mult=1.0):
    """Apply radial knockback from a comet impact — one-shot impulse (no PHYSICS_TIMESTEP)"""
    for beetle in [beetles[0], beetles[1]]:
        if beetle.active and not beetle.is_falling:
            dx = beetle.x - impact_x
            dz = beetle.z - impact_z
            dist = math.sqrt(dx * dx + dz * dz)
            if dist < radius:
                falloff = 1.0 - (dist / radius)
                if dist > 0.5:
                    dir_x, dir_z = dx / dist, dz / dist
                else:
                    dir_x = math.cos(beetle.rotation)
                    dir_z = math.sin(beetle.rotation)
                beetle.vx += dir_x * COMET_PUSH_FORCE * falloff * force_mult
                beetle.vz += dir_z * COMET_PUSH_FORCE * falloff * force_mult
                beetle.vy += COMET_LIFT_FORCE * falloff * force_mult
                # Tipping torque
                tip_mag = COMET_TIP_STRENGTH * falloff * force_mult
                cos_r = math.cos(beetle.rotation)
                sin_r = math.sin(beetle.rotation)
                local_x = dir_x * cos_r + dir_z * sin_r
                local_z = -dir_x * sin_r + dir_z * cos_r
                beetle.roll_velocity += local_x * tip_mag / max(beetle.roll_inertia, 0.1)
                beetle.pitch_velocity += local_z * tip_mag / max(beetle.pitch_inertia, 0.1)
                # Sustained shove from floor explosion
                comet_shove_effects.append([beetle, dir_x, dir_z, COMET_SHOVE_DURATION, COMET_SHOVE_FORCE * falloff * force_mult, COMET_SHOVE_TIP * falloff * force_mult])
                # Visual explosion at beetle
                spawn_spray_explosion(beetle.x, beetle.y + RENDER_Y_OFFSET, beetle.z, 1.0, 0.5, 0.1)
    # Ball knockback (3x force like UFO)
    if beetle_ball.active and not beetle_ball.is_falling:
        dx = beetle_ball.x - impact_x
        dz = beetle_ball.z - impact_z
        dist = math.sqrt(dx * dx + dz * dz)
        if dist < radius:
            falloff = 1.0 - (dist / radius)
            if dist > 0.5:
                dir_x, dir_z = dx / dist, dz / dist
            else:
                dir_x, dir_z = 1.0, 0.0
            beetle_ball.vx += dir_x * COMET_PUSH_FORCE * 3.0 * falloff * force_mult
            beetle_ball.vz += dir_z * COMET_PUSH_FORCE * 3.0 * falloff * force_mult
            beetle_ball.vy += COMET_LIFT_FORCE * 3.0 * falloff * force_mult

# ============== BOARD BREAK HAZARD FUNCTIONS ==============

def generate_board_break_pattern(rng=None):
    """Generate a random board break cutout pattern. Returns (pattern_spots, edge_spots, mask_np).
    Uses provided RNG for deterministic network sync, or global random if None."""
    import numpy as np
    if rng is None:
        rng = random

    pattern = rng.choice(['strip', 'cross', 'wedges', 'ring', 'circles', 'smiley', 'checkerboard'])
    center = 64.0
    floor_j = int(RENDER_Y_OFFSET)

    # Get floor mask (which cells are floor voxels)
    voxel_np = simulation.voxel_type.to_numpy()
    floor_slice = voxel_np[:, floor_j, :]
    is_floor = np.logical_or(floor_slice == 2, floor_slice == 21)  # CONCRETE or SLIPPERY

    # Create grid coordinate arrays
    gi_arr = np.arange(128)
    gk_arr = np.arange(128)
    GI, GK = np.meshgrid(gi_arr, gk_arr, indexing='ij')
    DI = GI - center
    DK = GK - center

    broken = np.zeros((128, 128), dtype=bool)

    if pattern == 'strip':
        angle = rng.uniform(0, math.pi)
        dist = np.abs(DI * math.sin(angle) - DK * math.cos(angle))
        broken = dist < BOARD_BREAK_STRIP_WIDTH / 2.0

    elif pattern == 'cross':
        angle = rng.uniform(0, math.pi / 2)
        dist1 = np.abs(DI * math.sin(angle) - DK * math.cos(angle))
        dist2 = np.abs(DI * math.cos(angle) + DK * math.sin(angle))
        broken = np.logical_or(dist1 < BOARD_BREAK_CROSS_ARM / 2.0,
                               dist2 < BOARD_BREAK_CROSS_ARM / 2.0)

    elif pattern == 'wedges':
        base_angle = rng.uniform(0, math.pi)
        half_wedge = math.radians(BOARD_BREAK_WEDGE_ANGLE / 2.0)
        cell_angles = np.arctan2(DK, DI)
        diff1 = np.abs(((cell_angles - base_angle + math.pi) % (2 * math.pi)) - math.pi)
        diff2 = np.abs(((cell_angles - (base_angle + math.pi) + math.pi) % (2 * math.pi)) - math.pi)
        broken = np.logical_or(diff1 < half_wedge, diff2 < half_wedge)

    elif pattern == 'ring':
        dist = np.sqrt(DI * DI + DK * DK)
        broken = np.logical_and(dist > BOARD_BREAK_RING_INNER, dist < BOARD_BREAK_RING_OUTER)

    elif pattern == 'circles':
        # Two random circles, same radius as the hole hazard, guaranteed spacing
        r = HOLE_RADIUS
        wander = 18.0
        min_dist = r * 2.5  # minimum distance between circle centers
        cx1 = center + rng.uniform(-wander, wander)
        ck1 = center + rng.uniform(-wander, wander)
        # Place second circle with minimum distance from first
        for _attempt in range(20):
            cx2 = center + rng.uniform(-wander, wander)
            ck2 = center + rng.uniform(-wander, wander)
            if math.sqrt((cx2 - cx1) ** 2 + (ck2 - ck1) ** 2) >= min_dist:
                break
        d1 = np.sqrt((GI - cx1) ** 2 + (GK - ck1) ** 2)
        d2 = np.sqrt((GI - cx2) ** 2 + (GK - ck2) ** 2)
        broken = np.logical_or(d1 < r, d2 < r)

    elif pattern == 'smiley':
        # Smiley or frowny face — randomly chosen each cycle
        is_frown = rng.random() < 0.5
        eye_r = 10.0
        eye_spread = 15.0
        eye_up = 12.0
        # Left eye
        d_left = np.sqrt((DI + eye_spread) ** 2 + (DK + eye_up) ** 2)
        broken = np.logical_or(broken, d_left < eye_r)
        # Right eye
        d_right = np.sqrt((DI - eye_spread) ** 2 + (DK + eye_up) ** 2)
        broken = np.logical_or(broken, d_right < eye_r)
        if not is_frown:
            # Smile: arc bottom + flat top
            mouth_cy = -4.0
            mouth_outer = 26.0
            d_mouth = np.sqrt(DI ** 2 + (DK - mouth_cy) ** 2)
            mouth_top_z = 8.0
            inside_arc = d_mouth < mouth_outer
            below_line = DK > mouth_top_z
            mouth_mask = np.logical_and(inside_arc, below_line)
        else:
            # Frown: arc top + flat bottom (inverted smile), shifted down from eyes
            mouth_cy = 34.0  # arc center further below
            mouth_outer = 26.0
            d_mouth = np.sqrt(DI ** 2 + (DK - mouth_cy) ** 2)
            mouth_bottom_z = 18.0  # flat line across the bottom
            inside_arc = d_mouth < mouth_outer
            above_line = DK < mouth_bottom_z
            mouth_mask = np.logical_and(inside_arc, above_line)
        broken = np.logical_or(broken, mouth_mask)

    elif pattern == 'heart':
        # Big heart shape — two overlapping circles on top + triangle bottom
        heart_scale = 24.0  # fills most of the arena
        lobe_r = heart_scale * 0.5  # radius of each lobe
        lobe_spread = heart_scale * 0.42  # horizontal offset for each lobe
        lobe_up = 4.0  # lobes sit above center
        # Left lobe
        d_ll = np.sqrt((DI + lobe_spread) ** 2 + (DK + lobe_up) ** 2)
        broken = np.logical_or(broken, d_ll < lobe_r)
        # Right lobe
        d_rl = np.sqrt((DI - lobe_spread) ** 2 + (DK + lobe_up) ** 2)
        broken = np.logical_or(broken, d_rl < lobe_r)
        # V-shape below lobes — starts where lobes end, matches their width
        lobe_bottom = -lobe_up + lobe_r  # DK where lobes end (bottom of circles)
        tip_z = lobe_bottom + heart_scale * 0.55  # point below lobes
        # At lobe_bottom, width = 2 * lobe_spread (circles have zero radius there)
        v_top_half_width = lobe_spread
        below_lobes = DK > lobe_bottom
        above_tip = DK < tip_z
        # Linear taper from lobe_spread at lobe_bottom to 0 at tip_z
        frac = np.clip((DK - lobe_bottom) / (tip_z - lobe_bottom), 0.0, 1.0)
        half_w = v_top_half_width * (1.0 - frac)
        in_taper = np.abs(DI) < half_w
        tri_mask = in_taper & below_lobes & above_tip
        broken = np.logical_or(broken, tri_mask)

    elif pattern == 'checkerboard':
        # Checkerboard: 2x2 grid that evenly divides the arena into 4 big squares
        # Anchor to center so pattern covers full floor with no slivers
        square_size = 38
        si = (GI.astype(int) - 64 + square_size) // square_size
        sk = (GK.astype(int) - 64 + square_size) // square_size
        broken = (si + sk) % 2 == 0

    # Intersect with actual floor voxels
    mask = np.logical_and(broken, is_floor).astype(np.int32)

    # Collect pattern spots
    pattern_spots = list(zip(*np.where(mask == 1)))

    # Edge spots: broken cells with at least one non-broken neighbor
    padded = np.pad(mask, 1, mode='constant', constant_values=0)
    has_solid_neighbor = (
        (padded[:-2, 1:-1] == 0) | (padded[2:, 1:-1] == 0) |
        (padded[1:-1, :-2] == 0) | (padded[1:-1, 2:] == 0)
    )
    edge_mask = np.logical_and(mask == 1, has_solid_neighbor)
    edge_spots_raw = list(zip(*np.where(edge_mask)))

    # Sort edge spots into perimeter order using nearest-neighbor chain
    # so sawblade cursors travel smoothly along the cut line
    edge_set = set(edge_spots_raw)
    remaining = set(edge_spots_raw)
    edge_spots = []
    while remaining:
        # Start a new chain from an arbitrary remaining spot
        start = next(iter(remaining))
        chain = [start]
        remaining.remove(start)
        while True:
            ci, ck = chain[-1]
            # Find nearest unvisited neighbor (8-connectivity first, then wider)
            best = None
            best_dist = 999999.0
            for ni, nk in remaining:
                d = abs(ni - ci) + abs(nk - ck)  # Manhattan for speed
                if d < best_dist:
                    best_dist = d
                    best = (ni, nk)
            if best is None or best_dist > 3:  # gap too large = new component
                break
            chain.append(best)
            remaining.remove(best)
        edge_spots.extend(chain)

    return pattern_spots, edge_spots, mask


@ti.kernel
def spawn_board_break_telegraph(spot_x: ti.f32, spot_z: ti.f32, phase: ti.f32):
    """Spawn a single tight warning particle at a board break edge spot — flashing red"""
    floor_y = RENDER_Y_OFFSET + 0.5
    pulse = 0.5 + 0.5 * ti.sin(phase * 6.0)
    flash = 0.5 + 0.5 * ti.sin(phase * 14.0)
    idx = ti.atomic_add(simulation.num_debris[None], 1)
    if idx < simulation.MAX_DEBRIS:
        simulation.debris_active[idx] = 1
        ti.atomic_add(simulation.debris_active_count[None], 1)
        # Tight scatter — stay close to the edge cell
        px = spot_x + (ti.random() - 0.5) * 0.6
        pz = spot_z + (ti.random() - 0.5) * 0.6
        spawn_y = floor_y + ti.random() * 0.3
        simulation.debris_pos[idx] = ti.math.vec3(px, spawn_y, pz)
        vx = (ti.random() - 0.5) * 0.5
        vz = (ti.random() - 0.5) * 0.5
        vy = 0.8 + ti.random() * 1.5
        simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)
        cr = 0.85 + flash * 0.15
        cg = 0.08 + (1.0 - flash) * 0.22 + pulse * 0.1
        cb = 0.02 + ti.random() * 0.03
        simulation.debris_material[idx] = ti.math.vec3(cr, cg, cb)
        simulation.debris_lifetime[idx] = 0.12 + ti.random() * 0.12


@ti.kernel
def spawn_board_break_saw(spot_x: ti.f32, spot_z: ti.f32, dir_x: ti.f32, dir_z: ti.f32, phase: ti.f32):
    """Spawn a sawblade — semicircular arc poking up through floor, disc aligned with cut line"""
    floor_y = RENDER_Y_OFFSET + 0.5
    blade_radius = 1.575
    num_arc = 14
    num_sparks = 4
    spin = phase * 8.0  # slower spin so red/black stripes are visible

    # Blade disc is in the (dir, Y) plane — tips touch floor along the cut line
    # dir_x/dir_z = travel direction along perimeter = lateral spread of blade
    # Perpendicular to travel (points into/out of cutout) used for spark spray
    perp_x = -dir_z
    perp_z = dir_x

    # --- Filled semicircular blade disc (spinning pinwheel) ---
    # Dense fill: 8 rings, more particles per ring = ~120 particles per saw
    n_rings = 8
    for ring in range(n_rings):
        ring_frac = (float(ring) + 1.0) / float(n_rings)
        r = blade_radius * ring_frac
        n_pts = 3 + ring * 2  # 3,5,7,9,11,13,15,17 = 80 total
        for i in range(n_pts):
            idx = ti.atomic_add(simulation.num_debris[None], 1)
            if idx < simulation.MAX_DEBRIS:
                simulation.debris_active[idx] = 1
                ti.atomic_add(simulation.debris_active_count[None], 1)
                frac = float(i) / float(ti.max(n_pts - 1, 1))
                angle = frac * 3.14159
                lateral = ti.cos(angle) * r
                height = ti.sin(angle) * r
                px = spot_x + dir_x * lateral
                pz = spot_z + dir_z * lateral
                py = floor_y + height
                simulation.debris_pos[idx] = ti.math.vec3(px, py, pz)
                simulation.debris_vel[idx] = ti.math.vec3(0.0, 0.0, 0.0)
                # Solid bright red blade
                simulation.debris_material[idx] = ti.math.vec3(0.95, 0.05, 0.02)
                simulation.debris_lifetime[idx] = 0.45  # above 0.4 fade threshold so color renders full

    # --- Contact sparks where blade tips meet the floor ---
    for i in range(num_sparks):
        idx = ti.atomic_add(simulation.num_debris[None], 1)
        if idx < simulation.MAX_DEBRIS:
            simulation.debris_active[idx] = 1
            ti.atomic_add(simulation.debris_active_count[None], 1)
            # Sparks at the two tip points (ahead/behind along cut line at floor level)
            side = 1.0 if i < num_sparks / 2 else -1.0
            px = spot_x + dir_x * blade_radius * side + (ti.random() - 0.5) * 0.5
            pz = spot_z + dir_z * blade_radius * side + (ti.random() - 0.5) * 0.5
            py = floor_y + ti.random() * 0.3
            simulation.debris_pos[idx] = ti.math.vec3(px, py, pz)
            # Sparks spray outward (perpendicular to cut) + upward
            spark_str = 2.0 + ti.random() * 3.0
            perp_side = 1.0 if ti.random() > 0.5 else -1.0
            vx = perp_x * perp_side * spark_str + (ti.random() - 0.5) * 1.5
            vz = perp_z * perp_side * spark_str + (ti.random() - 0.5) * 1.5
            vy = 1.5 + ti.random() * 3.0
            simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)
            # Bright orange-yellow sparks
            cr = 1.0
            cg = 0.7 + ti.random() * 0.3
            cb = 0.1 + ti.random() * 0.2
            simulation.debris_material[idx] = ti.math.vec3(cr, cg, cb)
            simulation.debris_lifetime[idx] = 0.12 + ti.random() * 0.15


@ti.kernel
def spawn_board_break_vibrate(spot_x: ti.f32, spot_z: ti.f32):
    """Spawn a small stone-colored particle vibrating on the floor surface"""
    floor_y = RENDER_Y_OFFSET + 0.5
    idx = ti.atomic_add(simulation.num_debris[None], 1)
    if idx < simulation.MAX_DEBRIS:
        simulation.debris_active[idx] = 1
        ti.atomic_add(simulation.debris_active_count[None], 1)
        px = spot_x + (ti.random() - 0.5) * 0.6
        pz = spot_z + (ti.random() - 0.5) * 0.6
        py = floor_y + ti.random() * 0.4
        simulation.debris_pos[idx] = ti.math.vec3(px, py, pz)
        # Tiny jitter velocity — vibrating in place
        vx = (ti.random() - 0.5) * 1.5
        vz = (ti.random() - 0.5) * 1.5
        vy = 0.5 + ti.random() * 1.5
        simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)
        # Mixed dark/bright stone colors
        grey = 0.05 + ti.random() * 0.85  # very wide: near-black (0.05) to bright (0.90)
        simulation.debris_material[idx] = ti.math.vec3(grey, grey * 0.95, grey * 0.9)
        simulation.debris_radius[idx] = 0.0  # use default radius (won't corrupt other particles)
        simulation.debris_lifetime[idx] = 0.15 + ti.random() * 0.1


@ti.kernel
def spawn_board_break_debris(spot_x: ti.f32, spot_z: ti.f32, upward: ti.f32):
    """Spawn stone debris burst at a board break edge — upward=1 for respawn, -1 for break"""
    floor_y = RENDER_Y_OFFSET + 0.5
    for i in range(5):
        idx = ti.atomic_add(simulation.num_debris[None], 1)
        if idx < simulation.MAX_DEBRIS:
            simulation.debris_active[idx] = 1
            ti.atomic_add(simulation.debris_active_count[None], 1)
            px = spot_x + (ti.random() - 0.5) * 1.0
            pz = spot_z + (ti.random() - 0.5) * 1.0
            simulation.debris_pos[idx] = ti.math.vec3(px, floor_y, pz)
            vx = (ti.random() - 0.5) * 8.0
            vz = (ti.random() - 0.5) * 8.0
            vy = upward * (3.0 + ti.random() * 6.0)
            simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)
            # Stone-colored debris
            grey = 0.35 + ti.random() * 0.15
            simulation.debris_material[idx] = ti.math.vec3(grey, grey * 0.95, grey * 0.9)
            simulation.debris_lifetime[idx] = 0.3 + ti.random() * 0.3


@ti.kernel
def spawn_board_break_saw_explode(spot_x: ti.f32, spot_z: ti.f32):
    """Explode a sawblade into a burst of red/orange shrapnel"""
    floor_y = RENDER_Y_OFFSET + 0.5
    for i in range(20):
        idx = ti.atomic_add(simulation.num_debris[None], 1)
        if idx < simulation.MAX_DEBRIS:
            simulation.debris_active[idx] = 1
            ti.atomic_add(simulation.debris_active_count[None], 1)
            px = spot_x + (ti.random() - 0.5) * 2.0
            pz = spot_z + (ti.random() - 0.5) * 2.0
            py = floor_y + ti.random() * 2.0
            simulation.debris_pos[idx] = ti.math.vec3(px, py, pz)
            vx = (ti.random() - 0.5) * 12.0
            vz = (ti.random() - 0.5) * 12.0
            vy = 3.0 + ti.random() * 8.0
            simulation.debris_vel[idx] = ti.math.vec3(vx, vy, vz)
            # Red/orange shrapnel
            cr = 0.8 + ti.random() * 0.2
            cg = 0.1 + ti.random() * 0.3
            cb = ti.random() * 0.05
            simulation.debris_material[idx] = ti.math.vec3(cr, cg, cb)
            simulation.debris_radius[idx] = 0.0  # use default radius
            simulation.debris_lifetime[idx] = 0.5 + ti.random() * 0.4


@ti.kernel
def clear_ladybug_voxels():
    """Clear all ladybug voxels from the grid (full scan - used for cleanup on disable)"""
    for i, j, k in ti.ndrange(simulation.n_grid, simulation.n_grid, simulation.n_grid):
        vtype = simulation.voxel_type[i, j, k]
        if vtype == simulation.LADYBUG_SHELL or vtype == simulation.LADYBUG_SPOTS or \
           vtype == simulation.LADYBUG_HEAD or vtype == simulation.LADYBUG_LEGS or \
           vtype == simulation.LADYBUG_WINGS:
            simulation.voxel_type[i, j, k] = simulation.EMPTY

@ti.kernel
def clear_ladybug_bounded(world_x: ti.f32, world_y: ti.f32, world_z: ti.f32):
    """Clear ladybug voxels using bounding box around position (much faster than full scan)"""
    # Ladybug shell radius 8, plus wings (~12), legs (~8), body tilt/roll extends further
    # Extra margin to cover movement between frames
    margin = 28

    center_x = int(world_x + simulation.n_grid / 2.0)
    center_y = int(world_y + RENDER_Y_OFFSET)
    center_z = int(world_z + simulation.n_grid / 2.0)

    min_x = ti.max(0, center_x - margin)
    max_x = ti.min(simulation.n_grid, center_x + margin)
    min_y = ti.max(0, center_y - margin)
    max_y = ti.min(simulation.n_grid, center_y + margin)
    min_z = ti.max(0, center_z - margin)
    max_z = ti.min(simulation.n_grid, center_z + margin)

    for i in range(min_x, max_x):
        for j in range(min_y, max_y):
            for k in range(min_z, max_z):
                vtype = simulation.voxel_type[i, j, k]
                if vtype == simulation.LADYBUG_SHELL or vtype == simulation.LADYBUG_SPOTS or \
                   vtype == simulation.LADYBUG_HEAD or vtype == simulation.LADYBUG_LEGS or \
                   vtype == simulation.LADYBUG_WINGS:
                    simulation.voxel_type[i, j, k] = simulation.EMPTY

@ti.kernel
def place_ladybug_kernel(world_x: ti.f32, world_y: ti.f32, world_z: ti.f32,
                         rotation: ti.f32, body_tilt: ti.f32, body_roll: ti.f32,
                         kick_phase: ti.f32, wing_phase: ti.f32, head_turn: ti.f32):
    """Place a ladybug at world position with rotation, tilt, roll, kick, wing flap, and head turn"""
    center_x = int(world_x + simulation.n_grid / 2.0)
    center_z = int(world_z + simulation.n_grid / 2.0)
    base_y = int(world_y + RENDER_Y_OFFSET)

    cos_rot = ti.cos(rotation)
    sin_rot = ti.sin(rotation)
    cos_tilt = ti.cos(body_tilt)
    sin_tilt = ti.sin(body_tilt)
    cos_roll = ti.cos(body_roll)
    sin_roll = ti.sin(body_roll)

    # Head turn rotation (around neck pivot point)
    cos_head = ti.cos(head_turn)
    sin_head = ti.sin(head_turn)
    head_pivot_x = 9.0  # Neck attachment point (where head meets body)

    # Wing flap - oscillates between -1 and +1 for clear visible movement
    wing_flap_amount = ti.sin(wing_phase)

    # Antenna wobble - trails behind body bob (forward/back sway)
    antenna_wobble = -ti.sin(wing_phase - 1.0) * 1.0  # Reduced to prevent gaps

    # Place body voxels
    for i in range(ladybug_body_cache_size[None]):
        local_x = float(ladybug_body_cache_x[i])
        local_y = float(ladybug_body_cache_y[i])
        local_z = float(ladybug_body_cache_z[i])
        vtype = ladybug_body_cache_type[i]

        # Head voxels (x >= 9) get independent head turn rotation
        if vtype == simulation.LADYBUG_HEAD and local_x >= 9.0:
            # Rotate around neck pivot point (head_pivot_x)
            rel_x = local_x - head_pivot_x
            rel_z = local_z
            local_x = head_pivot_x + rel_x * cos_head - rel_z * sin_head
            local_z = rel_x * sin_head + rel_z * cos_head

        # Antenna voxels get wobble (antennae are at y >= 4, x >= 13)
        extra_x = 0.0
        extra_y = 0.0
        if local_y >= 4.0 and local_x >= 13.0:
            # More wobble towards the tips (higher Y = further out)
            tip_factor = (local_y - 4.0) / 5.0  # 0 at base, 1 at tips
            extra_x = antenna_wobble * tip_factor  # Forward/back
            extra_y = antenna_wobble * tip_factor * 2.0  # Down more than forward

        # Apply body tilt (pitch back)
        tilted_x = (local_x + extra_x) * cos_tilt - (local_y - extra_y) * sin_tilt
        tilted_y = (local_x + extra_x) * sin_tilt + (local_y - extra_y) * cos_tilt

        # Apply body roll (left/right tilt) - rotates Y and Z
        rolled_y = tilted_y * cos_roll - local_z * sin_roll
        rolled_z = tilted_y * sin_roll + local_z * cos_roll

        # Apply world rotation (yaw)
        rotated_x = tilted_x * cos_rot - rolled_z * sin_rot
        rotated_z = tilted_x * sin_rot + rolled_z * cos_rot

        grid_x = center_x + int(ti.round(rotated_x))
        grid_y = base_y + int(ti.round(rolled_y))
        grid_z = center_z + int(ti.round(rotated_z))

        if 0 <= grid_x < simulation.n_grid and 0 <= grid_y < simulation.n_grid and 0 <= grid_z < simulation.n_grid:
            existing = simulation.voxel_type[grid_x, grid_y, grid_z]
            if existing != simulation.CONCRETE and existing != simulation.SHADOW and existing != simulation.SLIPPERY and existing != simulation.GOAL:
                simulation.voxel_type[grid_x, grid_y, grid_z] = vtype

    # Place wing voxels with flapping animation
    for wing_id in range(2):
        start_idx = ladybug_wing_start_idx[wing_id]
        end_idx = ladybug_wing_end_idx[wing_id]

        # Simple flap: outer wing voxels move up/down more than inner ones
        # Wing base is at z=±5, tips extend to z=±12
        wing_base_z = 5.0  # Inner edge distance from center

        for idx in range(start_idx, end_idx):
            local_x = float(ladybug_wing_cache_x[idx])
            local_y = float(ladybug_wing_cache_y[idx])
            local_z = float(ladybug_wing_cache_z[idx])

            # How far is this voxel from the wing base? (0 at base, ~7 at tip)
            dist_from_base = ti.abs(local_z) - wing_base_z

            # Flap offset: scales with distance from base (tips move ±3 voxels)
            flap_offset = dist_from_base * wing_flap_amount * 0.5

            flapped_y = local_y + flap_offset
            flapped_z = local_z

            # Apply body tilt
            tilted_x = local_x * cos_tilt - flapped_y * sin_tilt
            tilted_y = local_x * sin_tilt + flapped_y * cos_tilt

            # Apply body roll (left/right tilt)
            rolled_y = tilted_y * cos_roll - flapped_z * sin_roll
            rolled_z = tilted_y * sin_roll + flapped_z * cos_roll

            # Apply world rotation
            rotated_x = tilted_x * cos_rot - rolled_z * sin_rot
            rotated_z = tilted_x * sin_rot + rolled_z * cos_rot

            grid_x = center_x + int(ti.round(rotated_x))
            grid_y = base_y + int(ti.round(rolled_y))
            grid_z = center_z + int(ti.round(rotated_z))

            if 0 <= grid_x < simulation.n_grid and 0 <= grid_y < simulation.n_grid and 0 <= grid_z < simulation.n_grid:
                existing = simulation.voxel_type[grid_x, grid_y, grid_z]
                if existing != simulation.CONCRETE and existing != simulation.SHADOW and existing != simulation.SLIPPERY and existing != simulation.GOAL:
                    simulation.voxel_type[grid_x, grid_y, grid_z] = simulation.LADYBUG_WINGS

    # Place leg voxels with natural sway animation
    for leg_id in range(6):
        start_idx = ladybug_leg_start_idx[leg_id]
        end_idx = ladybug_leg_end_idx[leg_id]

        # Leg attachment points (scaled up for bigger body)
        attach_x = 0.0
        attach_z = 0.0
        if leg_id == 0:
            attach_x, attach_z = 3.0, -5.0
        elif leg_id == 1:
            attach_x, attach_z = 3.0, 5.0
        elif leg_id == 2:
            attach_x, attach_z = -1.0, -6.0
        elif leg_id == 3:
            attach_x, attach_z = -1.0, 6.0
        elif leg_id == 4:
            attach_x, attach_z = -5.0, -5.0
        else:
            attach_x, attach_z = -5.0, 5.0

        # Natural leg sway - trails behind body bob for organic dangling feel
        # Each leg pair has phase offset for wave effect (front to back)
        leg_row = leg_id // 2  # 0=front, 1=mid, 2=back
        leg_phase_offset = float(leg_row) * 0.4  # Slight delay back to front

        # Sway synced with wing phase (body bob) - legs splay outward with bounce
        # When body bobs up, legs spread out; when body drops, legs come back in
        sway_phase = wing_phase + leg_phase_offset
        leg_sway_amount = ti.sin(sway_phase) * 1.8  # Subtle but visible sway

        # Determine which side this leg is on based on Z (left=neg Z, right=pos Z)
        side = ti.select(attach_z < 0.0, -1.0, 1.0)

        for idx in range(start_idx, end_idx):
            # Calculate how far down the leg this voxel is (for graduated sway)
            leg_local_y = float(ladybug_leg_cache_y[idx])
            tip_factor = ti.max(0.0, (-leg_local_y) / 5.0)  # 0 at top, 1 at tips

            # Apply sway to Z axis (left-right) - legs splay outward to sides
            sway_offset = leg_sway_amount * tip_factor * side

            local_x = float(ladybug_leg_cache_x[idx]) + attach_x
            local_y = float(ladybug_leg_cache_y[idx]) - 1.0
            local_z = float(ladybug_leg_cache_z[idx]) + attach_z + sway_offset

            # Apply body tilt
            tilted_x = local_x * cos_tilt - local_y * sin_tilt
            tilted_y = local_x * sin_tilt + local_y * cos_tilt

            # Apply body roll (left/right tilt)
            rolled_y = tilted_y * cos_roll - local_z * sin_roll
            rolled_z = tilted_y * sin_roll + local_z * cos_roll

            # Apply world rotation
            rotated_x = tilted_x * cos_rot - rolled_z * sin_rot
            rotated_z = tilted_x * sin_rot + rolled_z * cos_rot

            grid_x = center_x + int(ti.round(rotated_x))
            grid_y = base_y + int(ti.round(rolled_y))
            grid_z = center_z + int(ti.round(rotated_z))

            if 0 <= grid_x < simulation.n_grid and 0 <= grid_y < simulation.n_grid and 0 <= grid_z < simulation.n_grid:
                existing = simulation.voxel_type[grid_x, grid_y, grid_z]
                if existing != simulation.CONCRETE and existing != simulation.SHADOW and existing != simulation.SLIPPERY and existing != simulation.GOAL:
                    simulation.voxel_type[grid_x, grid_y, grid_z] = simulation.LADYBUG_LEGS

def render_ladybug(ladybug, dt):
    """Render a single ladybug and update its animation"""
    if not ladybug.visible:
        return

    # Kick animation disabled for now - will implement later
    # ladybug.kick_phase += dt * 4.0
    # if ladybug.kick_phase > math.pi * 2:
    #     ladybug.kick_phase -= math.pi * 2

    # Update wing flap animation - gentle hovering speed
    ladybug.antenna_phase += dt * 8.0  # ~1.3 flaps per second for natural hover
    if ladybug.antenna_phase > math.pi * 2:
        ladybug.antenna_phase -= math.pi * 2

    # Update head turn animation - slower, independent look-around
    ladybug.head_turn_phase += dt * 1.5  # Slow head movement

    # Calculate head turn angle using multiple sine waves for organic feel
    head_turn = math.sin(ladybug.head_turn_phase * 0.7) * 0.35  # ±20 degrees main
    head_turn += math.sin(ladybug.head_turn_phase * 1.3) * 0.15  # ±9 degrees secondary

    # Bob up and down with wing beats (body rises as wings flap down)
    bob_offset = -math.sin(ladybug.antenna_phase) * 1.5  # ±1.5 voxels, inverted

    # Place voxels
    place_ladybug_kernel(ladybug.x, ladybug.y + bob_offset, ladybug.z,
                         ladybug.rotation, ladybug.body_tilt, ladybug.body_roll,
                         ladybug.kick_phase, ladybug.antenna_phase, head_turn)

    # Save current position for next frame's clearing
    ladybug.prev_x = ladybug.x
    ladybug.prev_y = ladybug.y
    ladybug.prev_z = ladybug.z

def spawn_test_ladybug():
    """Spawn a test ladybug in the center of the arena for preview"""
    global test_ladybug
    # Face toward camera (roughly toward -X, -Z which is where camera usually is)
    test_ladybug = Ladybug(0.0, 0.0, rotation=math.radians(-135))
    test_ladybug.y = 15.0  # Hovering above the arena
    test_ladybug.prev_y = 15.0  # Match initial y to prevent clearing at wrong height
    print("Test ladybug spawned hovering above arena center")

def clear_test_ladybug():
    """Remove the test ladybug"""
    global test_ladybug
    test_ladybug = None
    print("Test ladybug cleared")

def spawn_circle_ladybugs():
    """Spawn 8 ladybugs in a circle around the arena perimeter, facing center"""
    global active_ladybugs
    active_ladybugs.clear()

    num_ladybugs = 5
    spawn_radius = ARENA_RADIUS + 10  # Just outside arena edge
    hover_height = 7.0

    for i in range(num_ladybugs):
        # Position around circle
        angle = (2 * math.pi * i) / num_ladybugs
        x = math.cos(angle) * spawn_radius
        z = math.sin(angle) * spawn_radius

        # Face toward center (rotation = angle + 180 degrees)
        facing_center = angle + math.pi

        ladybug = Ladybug(x, z, rotation=facing_center)
        ladybug.y = hover_height
        ladybug.prev_y = hover_height  # Match initial y to prevent clearing at wrong height
        # Offset animation phase so they don't all sync
        ladybug.antenna_phase = (2 * math.pi * i) / num_ladybugs
        active_ladybugs.append(ladybug)

    print(f"Spawned {num_ladybugs} ladybugs in circle around arena")

def clear_circle_ladybugs():
    """Clear all circle ladybugs"""
    global active_ladybugs
    active_ladybugs.clear()
    print("Circle ladybugs cleared")

