# Beetle type list for slider cycling
BEETLE_TYPES = ["rhino", "stag", "hercules", "scorpion", "atlas", "bombardier", "spider", "giraffe"]

# Track current preset index per beetle
blue_preset_index = 66
red_preset_index = 67

def get_preset_palette(index):
    """Get a beetle color preset by index. Returns dict with body, legs, leg_tips, stripe, horn_tips."""
    return BEETLE_PRESETS[index % len(BEETLE_PRESETS)]

def apply_preset(palette, window, simulation, side):
    """Apply a preset palette to a beetle's window + simulation colors.
    side: 'blue' or 'red'"""
    setattr(window, f'{side}_body_color', palette['body'])
    setattr(window, f'{side}_leg_color', palette['legs'])
    setattr(window, f'{side}_leg_tip_color', palette['leg_tips'])
    setattr(window, f'{side}_stripe_color', palette['stripe'])
    setattr(window, f'{side}_horn_tip_color', palette['horn_tips'])
    getattr(simulation, f'{side}_body_color')[None] = ti.Vector(list(palette['body']))
    getattr(simulation, f'{side}_leg_color')[None] = ti.Vector(list(palette['legs']))
    getattr(simulation, f'{side}_leg_tip_color')[None] = ti.Vector(list(palette['leg_tips']))
    getattr(simulation, f'{side}_stripe_color')[None] = ti.Vector(list(palette['stripe']))
    getattr(simulation, f'{side}_horn_tip_color')[None] = ti.Vector(list(palette['horn_tips']))
    _gpu_color_cache.clear()

def apply_horn_defaults(beetle, horn_type):
    """Set horn pitch/yaw defaults for a given beetle type."""
    if horn_type == "scorpion":
        beetle.horn_pitch = HORN_DEFAULT_PITCH_SCORPION
        beetle.prev_horn_pitch = HORN_DEFAULT_PITCH_SCORPION
        beetle.horn_yaw = 0.0
    elif horn_type == "stag":
        beetle.horn_pitch = HORN_DEFAULT_PITCH_STAG
        beetle.prev_horn_pitch = HORN_DEFAULT_PITCH_STAG
        beetle.horn_yaw = HORN_DEFAULT_YAW_STAG
    elif horn_type == "hercules":
        beetle.horn_pitch = HORN_DEFAULT_PITCH_HERCULES
        beetle.prev_horn_pitch = HORN_DEFAULT_PITCH_HERCULES
        beetle.horn_yaw = 0.0
    elif horn_type == "atlas":
        beetle.horn_pitch = HORN_DEFAULT_PITCH_ATLAS
        beetle.prev_horn_pitch = HORN_DEFAULT_PITCH_ATLAS
        beetle.horn_yaw = 0.0
    elif horn_type == "bombardier":
        beetle.horn_pitch = 0.0
        beetle.prev_horn_pitch = 0.0
        beetle.horn_yaw = 0.0
    elif horn_type == "spider":
        beetle.horn_pitch = HORN_DEFAULT_PITCH_SCORPION
        beetle.prev_horn_pitch = HORN_DEFAULT_PITCH_SCORPION
        beetle.horn_yaw = 0.0
    else:  # rhino
        beetle.horn_pitch = HORN_DEFAULT_PITCH
        beetle.prev_horn_pitch = HORN_DEFAULT_PITCH
        beetle.horn_yaw = 0.0

def toggle_referee():
    """Toggle flying referee on/off (local only - doesn't sync over network)"""
    global referee_ladybug, referee_enabled, referee_time, referee_beam_active
    referee_enabled = not referee_enabled
    if referee_enabled:
        referee_ladybug = Ladybug(0.0, 0.0, rotation=0.0)
        referee_ladybug.y = 8.0
        referee_ladybug.prev_y = 8.0  # Match initial y to prevent clearing at wrong height
        referee_time = 0.0
        print("Flying referee ENABLED")
    else:
        # Clear the referee's voxels from the grid before removing
        clear_ladybug_voxels()
        referee_ladybug = None
        referee_beam_active = False  # Stop any active beam
        print("Flying referee DISABLED")

def update_referee_position(camera_angle, mid_x, mid_z, dt=0.016, stay_far=False):
    """Update referee position to stay opposite camera with organic exploration"""
    global referee_ladybug, referee_time
    if referee_ladybug is None or not referee_enabled:
        return

    # Accumulate time for organic movement
    referee_time += dt

    # Base position opposite the camera (180 degrees away)
    opposite_angle = camera_angle + math.pi

    # Organic variations using sine waves at different frequencies
    # Angle wander: ±40 degrees (~0.7 radians) at slow frequency - wider patrol arc
    angle_wander = math.sin(referee_time * 0.4) * 0.55
    angle_wander += math.sin(referee_time * 0.17) * 0.25  # Secondary slower wave

    # Radius breathing: only outward movement (never closer to center)
    if stay_far:
        # 3rd person mode: stay at max patrol range
        radius_breathe = 8.0  # Fixed at max distance
    else:
        radius_breathe = max(0, math.sin(referee_time * 0.25)) * 4.0
        radius_breathe += max(0, math.sin(referee_time * 0.6)) * 1.5  # Faster subtle variation

    # Apply variations to base position
    final_angle = opposite_angle + angle_wander
    # Keep within grid bounds to prevent wing/leg tips going out of bounds
    referee_radius = ARENA_RADIUS + 18 + radius_breathe

    target_x = math.cos(final_angle) * referee_radius
    target_z = math.sin(final_angle) * referee_radius

    # Speed variation: sometimes faster, sometimes slower (organic patrol feel)
    speed_variation = math.sin(referee_time * 0.3) * 0.04  # ±0.04
    speed_variation += math.sin(referee_time * 0.7) * 0.02  # Faster subtle variation
    move_speed = 0.08 + speed_variation  # Base 0.08, range 0.02 to 0.14

    # Smooth movement (lerp with variable speed, frame-rate independent)
    dt_factor = dt * 60.0  # Normalize to 60 FPS baseline
    referee_ladybug.x += (target_x - referee_ladybug.x) * move_speed * dt_factor
    referee_ladybug.z += (target_z - referee_ladybug.z) * move_speed * dt_factor

    # Look-around: face toward midpoint but with slight scanning motion
    dx = mid_x - referee_ladybug.x
    dz = mid_z - referee_ladybug.z
    base_rotation = math.atan2(dz, dx)

    # Look-around with much more turning (±50-60 degrees to show side profile)
    look_offset = math.sin(referee_time * 0.5) * 0.42
    look_offset += math.sin(referee_time * 0.23) * 0.24
    look_offset += math.sin(referee_time * 0.8) * 0.12

    # Smooth the rotation to reduce flickering (frame-rate independent)
    target_rotation = base_rotation + look_offset
    angle_diff = target_rotation - referee_ladybug.rotation
    # Normalize angle diff
    while angle_diff > math.pi:
        angle_diff -= 2 * math.pi
    while angle_diff < -math.pi:
        angle_diff += 2 * math.pi
    referee_ladybug.rotation += angle_diff * 0.15 * dt_factor

    # Forward/back tilt (±18 degrees on top of base 30 degree tilt)
    tilt_offset = math.sin(referee_time * 0.35) * 0.22
    tilt_offset += math.sin(referee_time * 0.6) * 0.1
    referee_ladybug.body_tilt = math.radians(30) + tilt_offset

    # Left/right roll (±12 degrees) - subtle banking during patrol
    roll_offset = math.sin(referee_time * 0.28) * 0.15  # ±9 degrees main
    roll_offset += math.sin(referee_time * 0.55) * 0.06  # ±3 degrees secondary
    referee_ladybug.body_roll = roll_offset

    # Slow vertical drift (±4 voxels on top of base height)
    height_drift = math.sin(referee_time * 0.2) * 3.0
    height_drift += math.sin(referee_time * 0.45) * 1.5
    referee_ladybug.y = 8.0 + height_drift

def get_referee_antenna_tips():
    """Get world positions of referee's antenna tips for beam effect"""
    if referee_ladybug is None:
        return None, None

    # Antenna tips are at local position roughly (head_x + 9, head_y + 8, ±spread)
    # head_x = 11, head_y = 2, so tips around (20, 10, ±5)
    # Apply body tilt and rotation transforms
    cos_rot = math.cos(referee_ladybug.rotation)
    sin_rot = math.sin(referee_ladybug.rotation)
    cos_tilt = math.cos(referee_ladybug.body_tilt)
    sin_tilt = math.sin(referee_ladybug.body_tilt)

    # Local antenna tip positions (approximate)
    local_x = 18.0
    local_y = 9.0
    local_z_left = -4.0
    local_z_right = 4.0

    # Apply tilt
    tilted_x = local_x * cos_tilt - local_y * sin_tilt
    tilted_y = local_x * sin_tilt + local_y * cos_tilt

    # Apply rotation for left antenna
    world_x_left = referee_ladybug.x + tilted_x * cos_rot - local_z_left * sin_rot
    world_z_left = referee_ladybug.z + tilted_x * sin_rot + local_z_left * cos_rot
    world_y = referee_ladybug.y + tilted_y

    # Apply rotation for right antenna
    world_x_right = referee_ladybug.x + tilted_x * cos_rot - local_z_right * sin_rot
    world_z_right = referee_ladybug.z + tilted_x * sin_rot + local_z_right * cos_rot

    return (world_x_left, world_y, world_z_left), (world_x_right, world_y, world_z_right)

# Referee beam state
referee_beam_active = False
referee_beam_timer = 0.0
referee_beam_target = None  # 'blue' or 'red'
referee_beam_hit_target = False  # True when beam head first reaches the score digit
REFEREE_BEAM_DURATION = 0.75  # Duration of beam effect (2x length)

@ti.kernel
def clear_referee_beam_voxels():
    """Clear ALL score digit colored voxels - they get re-rendered each frame anyway"""
    for i, j, k in ti.ndrange(simulation.n_grid, simulation.n_grid, simulation.n_grid):
        vtype = simulation.voxel_type[i, j, k]
        if vtype == simulation.SCORE_DIGIT_BLUE or vtype == simulation.SCORE_DIGIT_RED:
            simulation.voxel_type[i, j, k] = simulation.EMPTY

def get_referee_belly_position():
    """Get the bottom center of the referee ladybug's belly"""
    if referee_ladybug is None:
        return None
    # Belly is at center of ladybug, below the shell
    # The ladybug y is the base, shell goes up from there
    # Belly bottom is approximately at y - 1 (just below body center)
    return (referee_ladybug.x, referee_ladybug.y - 1.0, referee_ladybug.z)

# Magic beam voxel type - uses score digit color to match the target
@ti.kernel
def render_referee_beam(start_x: ti.f32, start_y: ti.f32, start_z: ti.f32,
                        end_x: ti.f32, end_y: ti.f32, end_z: ti.f32,
                        head_progress: ti.f32, tail_progress: ti.f32,
                        spiral_phase: ti.f32, beam_type: ti.i32):
    """Render a magical spiral beam from referee to score"""
    # Beam travels from start to end based on progress (0-1)
    # Head leads, tail follows - creates a traveling beam effect
    beam_length = ti.sqrt((end_x - start_x)**2 + (end_y - start_y)**2 + (end_z - start_z)**2)
    num_points = int(beam_length * 1.5)  # Points along beam

    for i in range(num_points):
        t = float(i) / float(num_points)

        # Only draw points between tail and head (traveling beam)
        if t > head_progress or t < tail_progress:
            continue

        # Base position along beam
        px = start_x + (end_x - start_x) * t
        py = start_y + (end_y - start_y) * t
        pz = start_z + (end_z - start_z) * t

        # Add spiral offset
        spiral_radius = 2.0 * (1.0 - t * 0.5)  # Spiral gets tighter toward end
        spiral_angle = spiral_phase + t * 12.0  # Multiple rotations along beam
        offset_x = ti.cos(spiral_angle) * spiral_radius
        offset_z = ti.sin(spiral_angle) * spiral_radius

        # Grid position (center of beam)
        center_x = int(px + offset_x + simulation.n_grid / 2.0)
        center_y = int(py + RENDER_Y_OFFSET)
        center_z = int(pz + offset_z + simulation.n_grid / 2.0)

        # Place a 2x2x2 cluster for thicker beam
        for dx in range(-1, 1):
            for dy in range(-1, 1):
                for dz in range(-1, 1):
                    grid_x = center_x + dx
                    grid_y = center_y + dy
                    grid_z = center_z + dz
                    if 0 <= grid_x < simulation.n_grid and 0 <= grid_y < simulation.n_grid and 0 <= grid_z < simulation.n_grid:
                        existing = simulation.voxel_type[grid_x, grid_y, grid_z]
                        if existing == simulation.EMPTY:
                            simulation.voxel_type[grid_x, grid_y, grid_z] = beam_type

def trigger_referee_beam(target):
    """Start the referee beam effect toward a score"""
    global referee_beam_active, referee_beam_timer, referee_beam_target, referee_beam_hit_target
    if referee_ladybug is None or not referee_enabled:
        return
    referee_beam_active = True
    referee_beam_timer = REFEREE_BEAM_DURATION
    referee_beam_target = target
    referee_beam_hit_target = False  # Reset hit flag when beam starts

def update_and_render_referee_beam(dt):
    """Update beam timer and render if active. Returns True if beam just hit target this frame."""
    global referee_beam_active, referee_beam_timer, referee_time, referee_beam_hit_target

    # Skip entirely if referee is disabled and beam is not active
    if not referee_enabled and not referee_beam_active:
        return

    # Clear beam voxels if beam is/was active (need to clear when beam ends too)
    if referee_beam_active:
        clear_referee_beam_voxels()

        referee_beam_timer -= dt
        if referee_beam_timer <= 0:
            referee_beam_active = False
            # Final clear already done above, just return
            return
    else:
        # Beam not active - smoothly decay leg wiggle
        if referee_ladybug is not None and referee_ladybug.kick_phase > 0:
            referee_ladybug.kick_phase = max(0.0, referee_ladybug.kick_phase - dt * 8.0)
        return

    # Animate leg wiggle while beam is active
    if referee_ladybug is not None:
        referee_ladybug.kick_phase += dt * 12.0  # Fast wiggle during beam

    # Get belly position as beam origin
    belly = get_referee_belly_position()
    if belly is None:
        return

    # Beam comes from bottom middle of belly
    start_x = belly[0]
    start_y = belly[1]
    start_z = belly[2]

    # Target position (score digit center)
    # Blue score at x=96, Red score at x=32, both at y=53, z=64
    # Overshoot slightly so beam really reaches the digit
    if referee_beam_target == 'blue':
        end_x = 96.0 - simulation.n_grid / 2.0  # Convert to world coords
        end_z = 64.0 - simulation.n_grid / 2.0
    else:
        end_x = 32.0 - simulation.n_grid / 2.0
        end_z = 64.0 - simulation.n_grid / 2.0
    # Target the center of the digit (y=53 in grid = 20 in world coords)
    # Overshoot significantly to ensure beam reaches the digit
    end_y = 53.0 - RENDER_Y_OFFSET + 6.0

    # Progress: head leads, tail follows (creates traveling beam effect)
    # Total animation: head goes 0->1, then tail catches up 0->1
    raw_progress = 1.0 - (referee_beam_timer / REFEREE_BEAM_DURATION)

    # Head moves fast, reaches end at 60% of duration
    head_progress = min(1.0, raw_progress * 1.7)
    # Tail follows behind, delayed by ~40% of the beam length
    tail_progress = max(0.0, (raw_progress - 0.3) * 1.5)
    tail_progress = min(1.0, tail_progress)

    # Detect when beam head first hits the target (triggers score explosion)
    if head_progress >= 1.0 and not referee_beam_hit_target:
        referee_beam_hit_target = True

    # Spiral phase for animation
    spiral_phase = referee_time * 15.0

    # Choose beam color based on scoring team
    if referee_beam_target == 'blue':
        beam_type = simulation.SCORE_DIGIT_BLUE
    else:
        beam_type = simulation.SCORE_DIGIT_RED

    render_referee_beam(start_x, start_y, start_z, end_x, end_y, end_z,
                        head_progress, tail_progress, spiral_phase, beam_type)

# ============== END LADYBUG CHEERLEADER SYSTEM ==============


@ti.kernel
def spawn_spray_explosion(pos_x: ti.f32, pos_y: ti.f32, pos_z: ti.f32,
                          color_r: ti.f32, color_g: ti.f32, color_b: ti.f32):
    """Explosion when spray hits beetle - small particles that spread out"""
    for i in range(16):  # 16 small particles
        idx = ti.atomic_add(simulation.num_debris[None], 1)
        if idx < simulation.MAX_DEBRIS:
            simulation.debris_active[idx] = 1  # Mark slot as active (free list pattern)
            ti.atomic_add(simulation.debris_active_count[None], 1)  # Track live count
            angle = ti.random() * 6.28318
            speed = 34.0 + ti.random() * 51.0  # 70% faster spread

            simulation.debris_pos[idx] = ti.math.vec3(pos_x, pos_y, pos_z)
            simulation.debris_vel[idx] = ti.math.vec3(
                ti.cos(angle) * speed,
                17.0 + ti.random() * 34.0,  # 70% higher pop
                ti.sin(angle) * speed
            )
            # Use passed color darkened slightly for explosion
            color_var = 0.7 + ti.random() * 0.3
            simulation.debris_material[idx] = ti.math.vec3(color_r * color_var * 0.6, color_g * color_var * 0.6, color_b * color_var * 0.6)
            simulation.debris_lifetime[idx] = 0.2 + ti.random() * 0.2  # 0.2-0.4s

@ti.kernel
def check_spray_voxel_collision_kernel(target_color: ti.i32, skip_owner: ti.i32):
    """GPU kernel: Check spray particles against beetle voxels. Sets spray_hit[idx]=1 if hit."""
    n_grid = simulation.n_grid
    num = simulation.num_spray[None]

    for idx in range(num):
        # Reset hit flag
        simulation.spray_hit[idx] = 0

        # Skip inactive particles (free list pattern)
        if simulation.spray_active[idx] == 0:
            continue
        # Skip if owned by target (don't hit own beetle)
        if simulation.spray_owner[idx] == skip_owner:
            continue
        # Grace period - skip very fresh particles (first ~0.05 sec)
        # Works for both spray (starts 0.6-0.9) and venom (starts 1.5-1.8)
        # Fresh spray: lifetime > 0.55, Fresh venom: lifetime > 1.45
        # We skip if lifetime is within 0.1 of max possible (1.8)
        if simulation.spray_lifetime[idx] > 1.7:
            continue

        # Get spray position
        spray_x = simulation.spray_pos[idx][0]
        spray_y = simulation.spray_pos[idx][1]
        spray_z = simulation.spray_pos[idx][2]

        # Convert to grid coordinates
        grid_x = int(spray_x + n_grid / 2.0)
        grid_y = int(spray_y)  # Already includes RENDER_Y_OFFSET
        grid_z = int(spray_z + n_grid / 2.0)

        # Check ±1 voxel neighborhood for beetle voxels (with early exit)
        hit = 0
        for dx in range(-1, 2):
            if hit == 0:  # Early exit at outer loop
                for dy in range(-1, 2):
                    if hit == 0:  # Early exit at middle loop
                        for dz in range(-1, 2):
                            if hit == 0:  # Early exit at inner loop
                                gx = grid_x + dx
                                gy = grid_y + dy
                                gz = grid_z + dz
                                # Bounds check
                                if 0 <= gx < n_grid and 0 <= gy < n_grid and 0 <= gz < n_grid:
                                    vtype = simulation.voxel_type[gx, gy, gz]
                                    # Check if voxel belongs to the target
                                    # player slot (target_color = slot, any part)
                                    if simulation.beetle_owner(vtype) == target_color and simulation.beetle_owner(vtype) >= 0:
                                        hit = 1

        if hit == 1:
            simulation.spray_hit[idx] = 1
            simulation.spray_hit_pos[idx] = ti.math.vec3(spray_x, spray_y, spray_z)

@ti.kernel
def spawn_score_burst(pos_x: ti.f32, pos_y: ti.f32, pos_z: ti.f32,
                      body_r: ti.f32, body_g: ti.f32, body_b: ti.f32,
                      leg_r: ti.f32, leg_g: ti.f32, leg_b: ti.f32,
                      stripe_r: ti.f32, stripe_g: ti.f32, stripe_b: ti.f32,
                      tip_r: ti.f32, tip_g: ti.f32, tip_b: ti.f32,
                      num_particles: ti.i32, start_index: ti.i32, total_particles: ti.i32):
    """Spawn celebratory particle burst when score changes - particles fly outward from digit center"""
    for i in range(num_particles):
        particle_i = start_index + i  # Use global index for distribution
        idx = ti.atomic_add(simulation.num_debris[None], 1)
        if idx < simulation.MAX_DEBRIS:
            simulation.debris_active[idx] = 1  # Mark slot as active (free list pattern)
            ti.atomic_add(simulation.debris_active_count[None], 1)  # Track live count
            # Spherical distribution using golden angle for even spread
            golden_angle = 3.14159 * (3.0 - ti.sqrt(5.0))
            theta = golden_angle * ti.cast(particle_i, ti.f32)
            # Vary elevation with some randomness
            phi = ti.acos(1.0 - 2.0 * (ti.cast(particle_i, ti.f32) + ti.random()) / ti.cast(total_particles, ti.f32))

            # Convert to direction
            sin_phi = ti.sin(phi)
            dir_x = sin_phi * ti.cos(theta)
            dir_y = ti.cos(phi)
            dir_z = sin_phi * ti.sin(theta)

            # Spawn at center with slight random offset
            spawn_x = pos_x + (ti.random() - 0.5) * 2.0
            spawn_y = pos_y + (ti.random() - 0.5) * 2.0
            spawn_z = pos_z + (ti.random() - 0.5) * 2.0

            simulation.debris_pos[idx] = ti.math.vec3(spawn_x, spawn_y, spawn_z)

            # Burst outward with varying speeds
            speed = 40.0 + ti.random() * 60.0  # 40-100 units/sec
            simulation.debris_vel[idx] = ti.math.vec3(dir_x * speed, dir_y * speed + 20.0, dir_z * speed)

            # Sample color from beetle colors (same distribution as victory confetti)
            # 55% body, 20% leg, 15% stripe, 10% tip
            rand = ti.random()
            particle_color = ti.math.vec3(body_r, body_g, body_b)  # Default to body
            if rand >= 0.55 and rand < 0.75:
                particle_color = ti.math.vec3(leg_r, leg_g, leg_b)
            elif rand >= 0.75 and rand < 0.90:
                particle_color = ti.math.vec3(stripe_r, stripe_g, stripe_b)
            elif rand >= 0.90:
                particle_color = ti.math.vec3(tip_r, tip_g, tip_b)

            # Add brightness variation (some particles brighter/whiter)
            brightness = 0.8 + ti.random() * 0.4  # 0.8-1.2x
            white_blend = ti.random() * 0.3  # 0-30% white blend for sparkle
            r = particle_color.x * brightness * (1.0 - white_blend) + white_blend
            g = particle_color.y * brightness * (1.0 - white_blend) + white_blend
            b = particle_color.z * brightness * (1.0 - white_blend) + white_blend
            simulation.debris_material[idx] = ti.math.vec3(r, g, b)

            # Short lifetime for snappy burst
            simulation.debris_lifetime[idx] = 0.4 + ti.random() * 0.4  # 0.4-0.8 sec

# Base leg tip offsets from beetle center (unrotated, in voxel units) for leg_length=6
# Beetle coordinate system: +X = forward (head), -X = backward (rear)
# +Z = left side, -Z = right side
# These get scaled by leg_length / 6.0
LEG_TIP_OFFSETS_BASE = [
    (2, 8),   # 0: front_left (forward, left)
    (2, -8),  # 1: front_right (forward, right)
    (-3, 11),  # 2: middle_left (center, far left)
    (-3, -11), # 3: middle_right (center, far right)
    (-10, 8),  # 4: rear_left (backward, left)
    (-10, -8), # 5: rear_right (backward, right)
    (-14, 8),  # 6: rear2_left (scorpion extra back left)
    (-14, -8), # 7: rear2_right (scorpion extra back right)
]

# Spider has legs attached further forward with different angles
# Spider prosoma is compact, legs don't spread out as much
SPIDER_LEG_TIP_OFFSETS = [
    (6, 7),    # 0: front_left (prosoma front, forward-left)
    (6, -7),   # 1: front_right (prosoma front, forward-right)
    (2, 10),   # 2: middle_left (mid-prosoma, sideways-left)
    (2, -10),  # 3: middle_right (mid-prosoma, sideways-right)
    (-6, 9),   # 4: rear_left (pedicel area, backward-left)
    (-6, -9),  # 5: rear_right (pedicel area, backward-right)
    (-8, 8),   # 6: rear2_left (back of prosoma, backward-left)
    (-8, -8),  # 7: rear2_right (back of prosoma, backward-right)
]

def get_leg_tip_world_position(beetle, leg_id, leg_length=8):
    """Calculate world position of leg tip based on beetle position, rotation, and leg length"""
    # Use spider-specific offsets for spider
    if beetle.horn_type == "spider":
        base_x, base_z = SPIDER_LEG_TIP_OFFSETS[leg_id]
    else:
        base_x, base_z = LEG_TIP_OFFSETS_BASE[leg_id]
    # Softer scaling - sqrt curve so longer legs don't push dust too far
    # At leg_length=6: scale=1.0, at leg_length=10: scale=1.29 (instead of 1.67)
    scale = math.sqrt(leg_length / 6.0)
    local_x = base_x * scale
    local_z = base_z * scale
    # Rotate by beetle facing
    cos_r = math.cos(beetle.rotation)
    sin_r = math.sin(beetle.rotation)
    world_x = beetle.x + local_x * cos_r - local_z * sin_r
    world_z = beetle.z + local_x * sin_r + local_z * cos_r
    return world_x, world_z

def calculate_horn_damping(beetle, collision_x, collision_y, collision_z, engagement_factor):
    """Calculate separate pitch and yaw damping based on their own rotation directions (Phase 2: Horn Clipping Prevention)"""
    # Get horn tip position
    horn_tip_x, horn_tip_y, horn_tip_z = calculate_horn_tip_position(beetle)

    # Vector from horn tip to collision point
    to_collision_x = collision_x - horn_tip_x
    to_collision_y = collision_y - horn_tip_y
    to_collision_z = collision_z - horn_tip_z

    # === PITCH DAMPING (R/Y controls - vertical movement) ===
    rotating_up = beetle.horn_pitch_velocity > 0.1
    rotating_down = beetle.horn_pitch_velocity < -0.1
    collision_above_tip = to_collision_y > 0.0

    # Calculate if pitch is rotating toward or away from collision
    pitch_toward = (rotating_up and collision_above_tip) or (rotating_down and not collision_above_tip)
    pitch_away = (rotating_up and not collision_above_tip) or (rotating_down and collision_above_tip)

    if pitch_toward:
        target_pitch_damping = HORN_DAMPING_INTO * engagement_factor
    elif pitch_away:
        target_pitch_damping = HORN_DAMPING_AWAY * engagement_factor
    else:
        target_pitch_damping = HORN_DAMPING_NEUTRAL * engagement_factor

    # === YAW DAMPING (V/B controls - horizontal spread) ===
    # Calculate horizontal direction to collision relative to beetle facing
    cos_r = math.cos(beetle.rotation)
    sin_r = math.sin(beetle.rotation)
    # Transform collision offset to beetle-local coordinates
    local_collision_x = to_collision_x * cos_r + to_collision_z * sin_r

    rotating_open = beetle.horn_yaw_velocity > 0.1   # Opening pincers / yawing outward
    rotating_close = beetle.horn_yaw_velocity < -0.1  # Closing pincers / yawing inward
    collision_outside = local_collision_x > 0.0  # Collision is in front/outside of horn arc

    # Calculate if yaw is rotating toward or away from collision
    yaw_toward = (rotating_open and collision_outside) or (rotating_close and not collision_outside)
    yaw_away = (rotating_open and not collision_outside) or (rotating_close and collision_outside)

    if yaw_toward:
        target_yaw_damping = HORN_DAMPING_INTO * engagement_factor
    elif yaw_away:
        target_yaw_damping = HORN_DAMPING_AWAY * engagement_factor
    else:
        target_yaw_damping = HORN_DAMPING_NEUTRAL * engagement_factor

    # Smooth interpolation to avoid jerky feel
    new_pitch_damping = beetle.horn_pitch_damping + (target_pitch_damping - beetle.horn_pitch_damping) * HORN_DAMPING_SMOOTHING
    new_yaw_damping = beetle.horn_yaw_damping + (target_yaw_damping - beetle.horn_yaw_damping) * HORN_DAMPING_SMOOTHING

    return new_pitch_damping, new_yaw_damping


def beetle_collision(b1, b2, params, precomputed_collision=None):
    """Handle collision with voxel-perfect detection, pushing, and horn leverage.

    precomputed_collision: result from the batched check_collision_pairs_kernel
    (main loop); None falls back to a standalone single-pair kernel launch."""
    collision_stats['pairs_checked'] += 1
    # Detect if this is a ball collision (ball uses different, gentler physics)
    is_ball_collision = (b1.horn_type == "ball" or b2.horn_type == "ball")

    # PREDICTIVE COLLISION CHECK: Prevent horn clipping during fast spins
    # Check if horn tips WILL BE close next frame, apply gentle preventive push
    # Only run when beetles are actually moving/spinning (prevents false positives at rest)
    b1_is_moving = abs(b1.angular_velocity) > 0.1 or abs(b1.vx) > 0.1 or abs(b1.vz) > 0.1
    b2_is_moving = abs(b2.angular_velocity) > 0.1 or abs(b2.vx) > 0.1 or abs(b2.vz) > 0.1
    either_moving = b1_is_moving or b2_is_moving

    if not is_ball_collision and either_moving:
        dt = PHYSICS_TIMESTEP
        predictive_threshold = params.get("PREDICTIVE_COLLISION_DIST", 8.0)
        predictive_push = params.get("PREDICTIVE_COLLISION_PUSH", 0.3)

        # Calculate predicted angles for both beetles (current + velocity * dt)
        pred_pitch1 = b1.horn_pitch + b1.horn_pitch_velocity * dt
        pred_yaw1 = b1.horn_yaw + b1.horn_yaw_velocity * dt
        pred_rotation1 = b1.rotation + b1.angular_velocity * dt

        pred_pitch2 = b2.horn_pitch + b2.horn_pitch_velocity * dt
        pred_yaw2 = b2.horn_yaw + b2.horn_yaw_velocity * dt
        pred_rotation2 = b2.rotation + b2.angular_velocity * dt

        # Get predicted tip positions (use function then apply predicted body rotation)
        # For b1: calculate tip with predicted pitch/yaw
        tip1_x, tip1_y, tip1_z = calculate_horn_tip_position_with_both(b1, pred_pitch1, pred_yaw1)
        # Adjust for predicted body rotation (undo current rotation, apply predicted)
        rel1_x = tip1_x - b1.x
        rel1_z = tip1_z - b1.z
        cos_curr1 = math.cos(b1.rotation)
        sin_curr1 = math.sin(b1.rotation)
        # Undo current rotation
        local1_x = rel1_x * cos_curr1 + rel1_z * sin_curr1
        local1_z = -rel1_x * sin_curr1 + rel1_z * cos_curr1
        # Apply predicted rotation
        cos_pred1 = math.cos(pred_rotation1)
        sin_pred1 = math.sin(pred_rotation1)
        pred_tip1_x = b1.x + local1_x * cos_pred1 - local1_z * sin_pred1
        pred_tip1_z = b1.z + local1_x * sin_pred1 + local1_z * cos_pred1
        pred_tip1_y = tip1_y

        # For b2: same process
        tip2_x, tip2_y, tip2_z = calculate_horn_tip_position_with_both(b2, pred_pitch2, pred_yaw2)
        rel2_x = tip2_x - b2.x
        rel2_z = tip2_z - b2.z
        cos_curr2 = math.cos(b2.rotation)
        sin_curr2 = math.sin(b2.rotation)
        local2_x = rel2_x * cos_curr2 + rel2_z * sin_curr2
        local2_z = -rel2_x * sin_curr2 + rel2_z * cos_curr2
        cos_pred2 = math.cos(pred_rotation2)
        sin_pred2 = math.sin(pred_rotation2)
        pred_tip2_x = b2.x + local2_x * cos_pred2 - local2_z * sin_pred2
        pred_tip2_z = b2.z + local2_x * sin_pred2 + local2_z * cos_pred2
        pred_tip2_y = tip2_y

        # Check 3D distance between predicted tips
        dx = pred_tip1_x - pred_tip2_x
        dy = pred_tip1_y - pred_tip2_y
        dz = pred_tip1_z - pred_tip2_z
        tip_dist = math.sqrt(dx*dx + dy*dy + dz*dz)

        # If tips will be close, apply gentle preventive separation
        if tip_dist < predictive_threshold and tip_dist > 0.1:
            collision_stats['predictive_pushes'] += 1
            # Normalize direction
            nx = dx / tip_dist
            ny = dy / tip_dist
            nz = dz / tip_dist

            # Gentle push - scale by how close they'll be (closer = stronger push)
            target_push = predictive_push * (1.0 - tip_dist / predictive_threshold)

            # Smooth the push (ramp up gradually instead of instant)
            smoothing = params.get("PREDICTIVE_COLLISION_SMOOTHING", 0.3)
            b1.predictive_push_x = b1.predictive_push_x * (1.0 - smoothing) + (nx * target_push) * smoothing
            b1.predictive_push_z = b1.predictive_push_z * (1.0 - smoothing) + (nz * target_push) * smoothing
            b2.predictive_push_x = b2.predictive_push_x * (1.0 - smoothing) + (-nx * target_push) * smoothing
            b2.predictive_push_z = b2.predictive_push_z * (1.0 - smoothing) + (-nz * target_push) * smoothing

            # Apply smoothed push
            b1.x += b1.predictive_push_x
            b1.z += b1.predictive_push_z
            b2.x += b2.predictive_push_x
            b2.z += b2.predictive_push_z
        else:
            # Decay push when not needed (smooth ramp down)
            decay = 0.8
            b1.predictive_push_x *= decay
            b1.predictive_push_z *= decay
            b2.predictive_push_x *= decay
            b2.predictive_push_z *= decay
    else:
        # Beetles not moving - decay any existing push values
        decay = 0.8
        b1.predictive_push_x *= decay
        b1.predictive_push_z *= decay
        b2.predictive_push_x *= decay
        b2.predictive_push_z *= decay

    # SHAFT/HEAD CYLINDER COLLISION CHECK: Catch shaft/attachment collisions that voxels miss
    # Check if opponent's body center is within a cylinder around each beetle's horn shaft
    # For spider/bombardier, this covers their forward head/prosoma area
    # Skip for first 30 physics frames to let geometry initialize
    if not is_ball_collision and physics_frame > 30:
        shaft_cylinder_radius = params.get("SHAFT_CYLINDER_RADIUS", 6.0)
        shaft_cylinder_push = params.get("SHAFT_CYLINDER_PUSH", 0.25)

        # All beetle types (scorpion claws treated like forward head area)
        b1_has_shaft = b1.horn_type in ("rhino", "stag", "hercules", "atlas", "spider", "bombardier", "scorpion", "giraffe")
        b2_has_shaft = b2.horn_type in ("rhino", "stag", "hercules", "atlas", "spider", "bombardier", "scorpion", "giraffe")

        # Larger radius for hornless/short-reach types to prevent body clipping
        # (Giraffe used to get +2.0 to fudge its bad straight-chord segment;
        # the two-segment model covers the real neck+head now, so standard
        # +1.5 like the other special types)
        b1_radius = shaft_cylinder_radius + 1.5 if b1.horn_type in ("spider", "bombardier", "scorpion", "giraffe") else shaft_cylinder_radius
        b2_radius = shaft_cylinder_radius + 1.5 if b2.horn_type in ("spider", "bombardier", "scorpion", "giraffe") else shaft_cylinder_radius

        if b1_has_shaft or b2_has_shaft:
            # Check b2's body against b1's shaft/head cylinder
            if b1_has_shaft:
                b1_shaft_cx, b1_shaft_cy, b1_shaft_cz, _b1_seg, _b1_t, dist_to_b1_shaft = \
                    _closest_on_horn_segments(horn_collision_segments(b1), b2.x, b2.y, b2.z)
                if dist_to_b1_shaft < b1_radius:
                    collision_stats['shaft_pushes'] += 1
                    # Push b2 away from b1's shaft/head
                    push_strength = shaft_cylinder_push * (1.0 - dist_to_b1_shaft / b1_radius)
                    # Direction: perpendicular out of the shaft (closest point on
                    # shaft toward b2's center). Center-to-center points along the
                    # horn, which lets sideways motion slide through.
                    dx = b2.x - b1_shaft_cx
                    dz = b2.z - b1_shaft_cz
                    dist = math.sqrt(dx*dx + dz*dz)
                    if dist < 0.1:
                        # Degenerate (center on shaft axis): fall back to center-to-center
                        dx = b2.x - b1.x
                        dz = b2.z - b1.z
                        dist = math.sqrt(dx*dx + dz*dz)
                    if dist > 0.1:
                        nx = dx / dist
                        nz = dz / dist
                        b2.x += nx * push_strength
                        b2.z += nz * push_strength
                        b1.x -= nx * push_strength * 0.3  # Slight counter-push
                        b1.z -= nz * push_strength * 0.3

            # Check b1's body against b2's shaft/head cylinder
            if b2_has_shaft:
                b2_shaft_cx, b2_shaft_cy, b2_shaft_cz, _b2_seg, _b2_t, dist_to_b2_shaft = \
                    _closest_on_horn_segments(horn_collision_segments(b2), b1.x, b1.y, b1.z)
                if dist_to_b2_shaft < b2_radius:
                    collision_stats['shaft_pushes'] += 1
                    # Push b1 away from b2's shaft/head (perpendicular out of the shaft)
                    push_strength = shaft_cylinder_push * (1.0 - dist_to_b2_shaft / b2_radius)
                    dx = b1.x - b2_shaft_cx
                    dz = b1.z - b2_shaft_cz
                    dist = math.sqrt(dx*dx + dz*dz)
                    if dist < 0.1:
                        # Degenerate (center on shaft axis): fall back to center-to-center
                        dx = b1.x - b2.x
                        dz = b1.z - b2.z
                        dist = math.sqrt(dx*dx + dz*dz)
                    if dist > 0.1:
                        nx = dx / dist
                        nz = dz / dist
                        b1.x += nx * push_strength
                        b1.z += nz * push_strength
                        b2.x -= nx * push_strength * 0.3  # Slight counter-push
                        b2.z -= nz * push_strength * 0.3

    # Voxel-overlap check: normally precomputed by the batched pairs kernel
    # (one launch for all pairs in the main loop); standalone kernel otherwise
    if precomputed_collision is None:
        has_collision = check_collision_kernel(b1.x, b1.z, b1.y, b2.x, b2.z, b2.y, b1.color, b2.color)
    else:
        has_collision = precomputed_collision

    if has_collision:
        # GPU-ACCELERATED: Calculate occupied voxels on GPU (no CPU transfer!)
        calculate_occupied_voxels_kernel(b1.x, b1.z, b1.color,
                                        beetle1_occupied_x, beetle1_occupied_z, beetle1_occupied_count)
        calculate_occupied_voxels_kernel(b2.x, b2.z, b2.color,
                                        beetle2_occupied_x, beetle2_occupied_z, beetle2_occupied_count)

        # GPU-ACCELERATED: Calculate collision point on GPU (no CPU transfer!)
        calculate_collision_point_kernel(0)  # overlap_count not used in kernel

        # Read results from GPU (minimal data transfer - just 5 values!)
        collision_x = collision_point_x[None]
        collision_y = collision_point_y[None]
        collision_z = collision_point_z[None]
        contact_count = collision_contact_count[None]
        has_horn_tips = collision_has_horn_tips[None]

        collision_stats['voxel_collisions'] += 1
        if contact_count > collision_stats['max_contact_count']:
            collision_stats['max_contact_count'] = contact_count
        # Track separately without stag pincer squeezes (hook interiors), whose
        # wrap-around contact is legitimately huge — this max is the clip signal
        if collision_has_hook_interiors[None] == 0 and contact_count > collision_stats['max_contact_no_hook']:
            collision_stats['max_contact_no_hook'] = contact_count

        # Collision detected! Calculate 3D collision geometry
        dx = b1.x - b2.x
        dz = b1.z - b2.z
        dist = math.sqrt(dx**2 + dz**2)

        if dist > 0.001:
            # Use GPU-calculated collision point or fallback to midpoint
            if contact_count > 0:
                collision_x /= contact_count
                collision_z /= contact_count
                collision_y /= contact_count
            else:
                collision_x = (b1.x + b2.x) / 2.0
                collision_z = (b1.z + b2.z) / 2.0
                collision_y = (b1.y + b2.y) / 2.0

            # Calculate 3D collision normal (from b2 to b1)
            # Include vertical component based on contact geometry
            dy = b1.y - b2.y
            dist_3d = math.sqrt(dx**2 + dy**2 + dz**2)

            if dist_3d > 0.001:
                instant_normal_x = dx / dist_3d
                instant_normal_y = dy / dist_3d
                instant_normal_z = dz / dist_3d
            else:
                # Fallback to horizontal normal
                instant_normal_x = dx / dist
                instant_normal_y = 0.0
                instant_normal_z = dz / dist

            # Apply exponential moving average to smooth collision normal (reduces jitter)
            # This prevents rapid oscillation when beetles are locked horn-to-horn
            # Also smooths Y to prevent jarring "jump" on first contact during horn pitch
            b1.contact_normal_x += (instant_normal_x - b1.contact_normal_x) * COLLISION_NORMAL_SMOOTHING
            b1.contact_normal_y += (instant_normal_y - b1.contact_normal_y) * COLLISION_NORMAL_SMOOTHING
            b1.contact_normal_z += (instant_normal_z - b1.contact_normal_z) * COLLISION_NORMAL_SMOOTHING
            b2.contact_normal_x += (-instant_normal_x - b2.contact_normal_x) * COLLISION_NORMAL_SMOOTHING
            b2.contact_normal_y += (-instant_normal_y - b2.contact_normal_y) * COLLISION_NORMAL_SMOOTHING
            b2.contact_normal_z += (-instant_normal_z - b2.contact_normal_z) * COLLISION_NORMAL_SMOOTHING

            # Use smoothed normal for all collision forces (prevents first-contact jump)
            normal_x = b1.contact_normal_x
            normal_y = b1.contact_normal_y
            normal_z = b1.contact_normal_z

            # HORN-SHAFT PENETRATION RESPONSE: stop bodies sliding sideways
            # through a horn shaft. The main impulse below acts along the
            # center-to-center normal, which has no component opposing motion
            # perpendicular to a horn — so a beetle driving into the side of a
            # horn slides straight through. When the voxel contact point sits
            # on a horn shaft (real overlap only — no ghost contacts), push
            # the other beetle perpendicularly out of the shaft, transfer
            # closing momentum, and apply natural lift/tilt from the shove.
            # Tip battles (tip voxels in contact, in front of the victim)
            # keep their existing physics untouched.
            # The BALL is covered too (as intruder only): a horn spearing the
            # ball gets the same perpendicular push-out + momentum transfer
            # (the ball previously had NO anti-clip coverage at all).
            if contact_count > 0:
                shaft_contact_dist = params.get("SHAFT_CONTACT_DIST", 4.5)
                shaft_pushout = params.get("SHAFT_PENETRATION_PUSHOUT", 0.35)
                shaft_vel_damp = params.get("SHAFT_PENETRATION_VEL_DAMP", 0.5)
                shaft_tilt = params.get("SHAFT_PENETRATION_TILT", 0.15)
                shaft_lift = params.get("SHAFT_PENETRATION_LIFT", 0.25)
                for shaft_owner, intruder in ((b1, b2), (b2, b1)):
                    if shaft_owner.horn_type not in ("rhino", "stag", "hercules", "atlas",
                                                     "spider", "bombardier", "scorpion", "giraffe"):
                        continue
                    _so_segs = horn_collision_segments(shaft_owner)
                    _scx, _scy, _scz, _sseg, _st_local, _sdist = _closest_on_horn_segments(
                        _so_segs, collision_x, collision_y, collision_z)
                    _nseg = len(_so_segs)
                    _st = (_sseg + _st_local) / _nseg  # global 0..1 along the whole horn
                    so_tip_x, so_tip_y, so_tip_z = _so_segs[-1][3], _so_segs[-1][4], _so_segs[-1][5]
                    # Contact must sit on the shaft (base through mid included —
                    # that's where bodies slip through; tip end has own handling)
                    if _sdist > shaft_contact_dist or _st < 0.02 or _st > 0.95:
                        continue
                    _px = intruder.x - _scx
                    _pz = intruder.z - _scz
                    _pdist = math.sqrt(_px*_px + _pz*_pz)
                    # Direct clip-depth signal: how close the shaft got to the
                    # victim's body center (core radius ~7-8; <5 = buried).
                    # Ball excluded: its radius is ~4, so ordinary surface
                    # contact would pollute the beetle clip metrics.
                    if intruder.horn_type != "ball":
                        if _pdist < collision_stats['min_shaft_center_dist']:
                            collision_stats['min_shaft_center_dist'] = _pdist
                        if _pdist < 5.0:
                            collision_stats['deep_clip_events'] += 1
                            _clip_key = f"{shaft_owner.horn_type}->{intruder.horn_type}"
                            collision_stats['deep_clip_by_type'][_clip_key] = \
                                collision_stats['deep_clip_by_type'].get(_clip_key, 0) + 1
                    # Track the OWNER's horn burial: drives the depth-aware
                    # turn clamp (turning stays free at surface contact, the
                    # hard wall returns as the horn buries into a body —
                    # radial push-out can't oppose a tangential base sweep)
                    _burial_now = max(0.0, 8.0 - _pdist)
                    if _burial_now > getattr(shaft_owner, 'horn_burial', 0.0):
                        shaft_owner.horn_burial = _burial_now
                    if _pdist < 0.1:
                        continue
                    # Tip voxels in the contact normally mean a tip battle
                    # (existing physics handles it) — EXCEPT when the horn is
                    # burying in from behind the victim, or the shaft already
                    # sits near their body center (deep clip). Those aren't
                    # jousts; the push-out must still fire.
                    if has_horn_tips == 1:
                        if intruder.horn_type == "ball":
                            # Tips striking the ball are the normal hit (main
                            # ball response handles them) — only rescue when
                            # the shaft is speared into the ball's core
                            if _pdist > 4.0:
                                continue
                        else:
                            _icos = math.cos(intruder.rotation)
                            _isin = math.sin(intruder.rotation)
                            _int_front = ((collision_x - intruder.x) * _icos +
                                          (collision_z - intruder.z) * _isin)
                            if _int_front > -1.0 and _pdist > 5.0:
                                continue  # genuine frontal tip contact — leave it alone
                    _pnx = _px / _pdist
                    _pnz = _pz / _pdist
                    # Horn articulation motion at the contact: pitching/yawing
                    # the horn moves the shaft too, not just body motion.
                    # Differentiate numerically via the predicted-tip helper
                    # (same one predictive collision trusts) — the shaft point
                    # at parameter t moves ~t times the tip's motion, since the
                    # base is the pivot and barely moves.
                    _horn_vx = 0.0
                    _horn_vy = 0.0
                    _horn_vz = 0.0
                    # Articulation only moves the ROTATING segment: for most
                    # types that's the whole shaft (t from the base pivot);
                    # for the giraffe the neck is fixed and only the head
                    # segment sweeps, scaling with t from the elbow pivot.
                    _artic_t = _st_local if _sseg == _nseg - 1 else 0.0
                    if _artic_t > 0.0 and (abs(shaft_owner.horn_pitch_velocity) > 0.02 or
                            abs(shaft_owner.horn_yaw_velocity) > 0.02):
                        _pt_x, _pt_y, _pt_z = calculate_horn_tip_position_with_both(
                            shaft_owner,
                            shaft_owner.horn_pitch + shaft_owner.horn_pitch_velocity * PHYSICS_TIMESTEP,
                            shaft_owner.horn_yaw + shaft_owner.horn_yaw_velocity * PHYSICS_TIMESTEP)
                        _horn_vx = _artic_t * (_pt_x - so_tip_x) / PHYSICS_TIMESTEP
                        _horn_vy = _artic_t * (_pt_y - so_tip_y) / PHYSICS_TIMESTEP
                        _horn_vz = _artic_t * (_pt_z - so_tip_z) / PHYSICS_TIMESTEP

                    # Closing speed at the contact: how fast the shaft (body
                    # motion + turn sweep + horn articulation) and the intruder's
                    # body are approaching along the outward normal. Positive = closing.
                    _own_cvx = shaft_owner.vx - (_scz - shaft_owner.z) * shaft_owner.angular_velocity + _horn_vx
                    _own_cvz = shaft_owner.vz + (_scx - shaft_owner.x) * shaft_owner.angular_velocity + _horn_vz
                    _int_cvx = intruder.vx - (_scz - intruder.z) * intruder.angular_velocity
                    _int_cvz = intruder.vz + (_scx - intruder.x) * intruder.angular_velocity
                    _closing = (_own_cvx - _int_cvx) * _pnx + (_own_cvz - _int_cvz) * _pnz
                    if _closing > 0.0:
                        # Momentum transfer: driving or sweeping a horn into a
                        # body shoves it, with a reaction on the horn owner.
                        # Resistance is natural — an intruder moving/turning
                        # away from the shaft reduces the closing speed.
                        intruder.vx += _pnx * _closing * shaft_vel_damp
                        intruder.vz += _pnz * _closing * shaft_vel_damp
                        shaft_owner.vx -= _pnx * _closing * shaft_vel_damp * 0.3
                        shaft_owner.vz -= _pnz * _closing * shaft_vel_damp * 0.3

                        # NATURAL TILT: an off-center shove tips the body away
                        # from the contact (same local-frame pattern as the
                        # horn tipping torque above). Ball skips tilt (its
                        # pitch/roll are rolling animation, not posture).
                        if intruder.horn_type != "ball":
                            _tcos = math.cos(intruder.rotation)
                            _tsin = math.sin(intruder.rotation)
                            _wlx = collision_x - intruder.x
                            _wlz = collision_z - intruder.z
                            _loc_x = _wlx * _tcos + _wlz * _tsin
                            _loc_z = _wlz * _tcos - _wlx * _tsin
                            _tilt_f = min(_closing, 15.0) * shaft_tilt
                            intruder.pending_pitch += _loc_z * _tilt_f / intruder.pitch_inertia
                            intruder.pending_roll -= _loc_x * _tilt_f / intruder.roll_inertia

                    # NATURAL LIFT: a shaft below the body's midline levers it
                    # upward. Vertical closing counts horn articulation (flicking
                    # the horn up under a body lifts even with no horizontal
                    # approach) plus relative body vertical motion. Uses the
                    # smoothed pending drain so it reads as a heave, not a pop.
                    # Ball: below-center check and a direct vy kick (the ball
                    # doesn't drain pending_lift) - scooping it launches it.
                    _vert_closing = shaft_owner.vy + _horn_vy - intruder.vy
                    _below_mid = intruder.y if intruder.horn_type == "ball" else intruder.y + 4.0
                    if _scy < _below_mid and (_closing > 0.0 or _vert_closing > 0.5):
                        _lift_speed = max(_closing, 0.0) + max(_vert_closing, 0.0)
                        if intruder.horn_type == "ball":
                            intruder.vy += min(_lift_speed * shaft_lift, 4.0)
                        else:
                            intruder.pending_lift += min(_lift_speed * shaft_lift, 4.0)
                    # Depth-proportional positional separation per step: a
                    # barely-touching shaft gets the gentle base push (mirrors
                    # the floor's capped push-out), a buried one (near the body
                    # center) gets up to ~4x so it's expelled in a few steps
                    # instead of ~20
                    _burial = max(0.0, 8.0 - _pdist)
                    _push_amt = shaft_pushout * (1.0 + _burial * 0.4)
                    intruder.x += _pnx * _push_amt
                    intruder.z += _pnz * _push_amt
                    shaft_owner.x -= _pnx * _push_amt * 0.3
                    shaft_owner.z -= _pnz * _push_amt * 0.3
                    collision_stats['shaft_penetration_fixes'] += 1

                # SHAFT-VS-SHAFT RESPONSE: base/shaft crossings (horn-vs-horn
                # with no tips in contact) previously had NO dedicated
                # separation - everything above resolves horn-vs-BODY, and
                # the center-to-center impulse can't oppose a tangential base
                # sweep, so bases ground through each other when turning or
                # articulating. Push both shafts apart along their closest-
                # point line, damp the closing velocity (incl. turn sweep +
                # horn articulation), and feed the crossing depth into
                # horn_burial so the depth-aware turn clamp engages on
                # base-vs-base grinds too.
                if not is_ball_collision:
                    _svs_types = ("rhino", "stag", "hercules", "atlas",
                                  "spider", "bombardier", "scorpion", "giraffe")
                    if b1.horn_type in _svs_types and b2.horn_type in _svs_types:
                        # Closest crossing across all segment combos (1x1 for
                        # ordinary horns; the giraffe contributes neck + head
                        # segments so elbow-region crossings are covered too)
                        _segs1 = horn_collision_segments(b1)
                        _segs2 = horn_collision_segments(b2)
                        _svs_best = None
                        for _i1 in range(len(_segs1)):
                            for _i2 in range(len(_segs2)):
                                _res = closest_points_between_segments(
                                    *_segs1[_i1], *_segs2[_i2])
                                if _svs_best is None or _res[8] < _svs_best[0][8]:
                                    _svs_best = (_res, _i1, _i2)
                        (_c1x, _c1y, _c1z, _c2x, _c2y, _c2z,
                         _ss_s_loc, _ss_t_loc, _ss_d) = _svs_best[0]
                        # Map to global 0..1 along each whole horn so the
                        # base->tip taper and tip-crossing limits keep meaning
                        _ss_s = (_svs_best[1] + _ss_s_loc) / len(_segs1)
                        _ss_t = (_svs_best[2] + _ss_t_loc) / len(_segs2)
                        # Shafts are thicker at the base: taper the crossing
                        # threshold from ~6.5 voxels (base-vs-base) to ~4
                        # toward the tips
                        _svs_far = max(_ss_s, _ss_t)
                        _svs_thick = params.get("SHAFT_VS_SHAFT_DIST", 6.5) - 2.5 * _svs_far
                        # Tip-end crossings (s or t near 1) belong to the tip
                        # physics. When tip voxels are in the contact, only
                        # clearly BASAL crossings fire (a tip touching
                        # something must not disable base separation - that
                        # blanket gate was why base merges slipped through)
                        _svs_param_limit = 0.7 if has_horn_tips == 1 else 0.9
                        if 0.01 < _ss_d < _svs_thick and _ss_s < _svs_param_limit and _ss_t < _svs_param_limit:
                            _svs_depth = _svs_thick - _ss_d
                            for _bb in (b1, b2):
                                if _svs_depth > getattr(_bb, 'horn_burial', 0.0):
                                    _bb.horn_burial = _svs_depth
                            # Horizontal separation axis between crossing points
                            _sepx = _c2x - _c1x
                            _sepz = _c2z - _c1z
                            _seph = math.sqrt(_sepx*_sepx + _sepz*_sepz)
                            if _seph < 0.05:
                                # Near-vertical crossing - fall back to the
                                # center-to-center axis
                                _sepx = b2.x - b1.x
                                _sepz = b2.z - b1.z
                                _seph = math.sqrt(_sepx*_sepx + _sepz*_sepz)
                            if _seph > 0.05:
                                _hx = _sepx / _seph
                                _hz = _sepz / _seph
                                # Contact-point velocities: body + turn sweep +
                                # horn articulation (numeric tip diff x param).
                                # Articulation only moves the ROTATING segment
                                # (whole shaft for most types; head only for
                                # giraffe - the neck segment is fixed)
                                _svs_as = _ss_s_loc if _svs_best[1] == len(_segs1) - 1 else 0.0
                                _svs_at = _ss_t_loc if _svs_best[2] == len(_segs2) - 1 else 0.0
                                _a1vx = _a1vz = _a2vx = _a2vz = 0.0
                                if _svs_as > 0.0 and (abs(b1.horn_pitch_velocity) > 0.02 or
                                        abs(b1.horn_yaw_velocity) > 0.02):
                                    _p1x, _p1y, _p1z = calculate_horn_tip_position_with_both(
                                        b1, b1.horn_pitch + b1.horn_pitch_velocity * PHYSICS_TIMESTEP,
                                        b1.horn_yaw + b1.horn_yaw_velocity * PHYSICS_TIMESTEP)
                                    _a1vx = _svs_as * (_p1x - _segs1[-1][3]) / PHYSICS_TIMESTEP
                                    _a1vz = _svs_as * (_p1z - _segs1[-1][5]) / PHYSICS_TIMESTEP
                                if _svs_at > 0.0 and (abs(b2.horn_pitch_velocity) > 0.02 or
                                        abs(b2.horn_yaw_velocity) > 0.02):
                                    _p2x, _p2y, _p2z = calculate_horn_tip_position_with_both(
                                        b2, b2.horn_pitch + b2.horn_pitch_velocity * PHYSICS_TIMESTEP,
                                        b2.horn_yaw + b2.horn_yaw_velocity * PHYSICS_TIMESTEP)
                                    _a2vx = _svs_at * (_p2x - _segs2[-1][3]) / PHYSICS_TIMESTEP
                                    _a2vz = _svs_at * (_p2z - _segs2[-1][5]) / PHYSICS_TIMESTEP
                                _v1x = b1.vx - (_c1z - b1.z) * b1.angular_velocity + _a1vx
                                _v1z = b1.vz + (_c1x - b1.x) * b1.angular_velocity + _a1vz
                                _v2x = b2.vx - (_c2z - b2.z) * b2.angular_velocity + _a2vx
                                _v2z = b2.vz + (_c2x - b2.x) * b2.angular_velocity + _a2vz
                                # Closing along the separation axis (b1 -> b2)
                                _svs_cl = (_v1x - _v2x) * _hx + (_v1z - _v2z) * _hz
                                # Depth-scaled like the horn-vs-body push-out:
                                # gentle at first touch, ~2.4x when deep
                                _svs_push = params.get("SHAFT_PENETRATION_PUSHOUT", 0.35) * (1.0 + _svs_depth * 0.4)
                                b1.x -= _hx * _svs_push * 0.5
                                b1.z -= _hz * _svs_push * 0.5
                                b2.x += _hx * _svs_push * 0.5
                                b2.z += _hz * _svs_push * 0.5
                                if _svs_cl > 0.0:
                                    _svs_damp = params.get("SHAFT_PENETRATION_VEL_DAMP", 0.5) * 0.5
                                    b1.vx -= _hx * _svs_cl * _svs_damp
                                    b1.vz -= _hz * _svs_cl * _svs_damp
                                    b2.vx += _hx * _svs_cl * _svs_damp
                                    b2.vz += _hz * _svs_cl * _svs_damp
                                collision_stats['shaft_vs_shaft_pushes'] += 1

            # HORN LEVERAGE: Strong vertical lift when contact is high (horn collision)
            # Ball collisions now treated like beetle collisions for consistent physics
            center_y = (b1.y + b2.y) / 2.0
            contact_height_above_center = collision_y - center_y

            # Check if collision is in front of either beetle (where horns are)
            # If collision is behind BOTH beetles, it's body-to-body
            if not is_ball_collision:
                # Get collision position in each beetle's local space
                world_dx1 = collision_x - b1.x
                world_dz1 = collision_z - b1.z
                cos_r1 = math.cos(b1.rotation)
                sin_r1 = math.sin(b1.rotation)
                local_x1 = world_dx1 * cos_r1 + world_dz1 * sin_r1  # front/back

                world_dx2 = collision_x - b2.x
                world_dz2 = collision_z - b2.z
                cos_r2 = math.cos(b2.rotation)
                sin_r2 = math.sin(b2.rotation)
                local_x2 = world_dx2 * cos_r2 + world_dz2 * sin_r2  # front/back

                # Horn contact if collision is in front of EITHER beetle
                is_horn_contact = local_x1 > 0 or local_x2 > 0
            else:
                is_horn_contact = False

            if is_horn_contact:
                # Mark beetles as in horn collision (blocks rotation during contact)
                # For ball collisions, only mark the beetle (not the ball)
                if is_ball_collision:
                    # Only block rotation on the beetle, not the ball
                    if b1.horn_type != "ball":
                        b1.in_horn_collision = True
                    if b2.horn_type != "ball":
                        b2.in_horn_collision = True
                else:
                    b1.in_horn_collision = True
                    b2.in_horn_collision = True

                # === PHASE 2: HORN ROTATION DAMPING ===
                # Calculate engagement factor (how much horn contact exists)
                normalized_contact_count = min(contact_count / HORN_ENGAGEMENT_CONTACT_THRESHOLD, 1.0)
                height_factor = min((contact_height_above_center - 2.0) / 8.0, 1.0)
                engagement_factor = (normalized_contact_count * (1.0 - HORN_ENGAGEMENT_HEIGHT_WEIGHT) +
                                    height_factor * HORN_ENGAGEMENT_HEIGHT_WEIGHT)

                # Boost engagement for tip collisions - tips should feel solid even with few voxels
                MIN_TIP_ENGAGEMENT = 0.65  # Minimum engagement when horn tips are involved
                if has_horn_tips == 1:
                    engagement_factor = max(engagement_factor, MIN_TIP_ENGAGEMENT)

                # Expose engagement for the input-side turn resistance (light
                # contact turns near full speed, deep lock turns at the floor)
                if not is_ball_collision:
                    b1.horn_engagement = engagement_factor
                    b2.horn_engagement = engagement_factor

                # Calculate separate pitch and yaw damping for beetles (not ball) based on their rotation directions
                if b1.horn_type != "ball":
                    b1.horn_pitch_damping, b1.horn_yaw_damping = calculate_horn_damping(
                        b1, collision_x, collision_y, collision_z, engagement_factor)
                if b2.horn_type != "ball":
                    b2.horn_pitch_damping, b2.horn_yaw_damping = calculate_horn_damping(
                        b2, collision_x, collision_y, collision_z, engagement_factor)

                # Skip lift/leverage combat physics for ball collisions (ball has its own physics below)
                # Only apply beetle-vs-beetle lift physics when no ball is involved
                if not is_ball_collision:
                    # Scale up vertical component based on height - logarithmic scaling for diminishing returns
                    # Clamp to 0 minimum to prevent math.log domain error for low collisions
                    raw_leverage = max(contact_height_above_center / 3.0, 0.0)
                    horn_leverage = min(math.log(raw_leverage + 1.0) * 2.0, 2.5)

                    # TIP vs SHAFT: Tips have full leverage, shaft hits have reduced leverage
                    # Shaft hits (no tip voxels) have less mechanical advantage
                    if has_horn_tips == 0:
                        shaft_leverage_mult = params.get("SHAFT_LEVERAGE_MULT", 0.4)
                        horn_leverage *= shaft_leverage_mult

                    # Add MASSIVE upward bias to the collision normal
                    normal_y += horn_leverage * 2.5  # 5x stronger than before!

                    # Re-normalize
                    norm_len = math.sqrt(normal_x**2 + normal_y**2 + normal_z**2)
                    if norm_len > 0.001:
                        normal_x /= norm_len
                        normal_y /= norm_len
                        normal_z /= norm_len

                    # SIMPLIFIED SYMMETRIC LIFTING - PURE VELOCITY (for debugging)
                    # Whoever is pressing their lift key (R/U) lifts the opponent
                    lift_impulse = horn_leverage * 30.0  # Upward kick

                    # Calculate where the collision is relative to each beetle's center
                    collision_above_b1 = collision_y - b1.y
                    collision_above_b2 = collision_y - b2.y

                    # PURE VELOCITY ADVANTAGE - who's actively pressing R or U?
                    # Positive velocity = tilting horn UP = you lift opponent
                    # Blue pressing R: b1.horn_pitch_velocity = +2.0
                    # Red pressing U: b2.horn_pitch_velocity = +2.0

                    # FIX: Some beetles have horn parts that don't move - detect which part is colliding
                    # and set velocity to 0 for fixed parts, or invert for opposite-moving parts
                    b1_effective_vel = b1.horn_pitch_velocity
                    b2_effective_vel = b2.horn_pitch_velocity

                    # Helper to get collision point in beetle's local space
                    def get_local_collision(beetle, col_x, col_y, col_z):
                        cos_r = math.cos(beetle.rotation)
                        sin_r = math.sin(beetle.rotation)
                        local_x = (col_x - beetle.x) * cos_r + (col_z - beetle.z) * sin_r
                        local_y = col_y - beetle.y
                        local_z = (col_z - beetle.z) * cos_r - (col_x - beetle.x) * sin_r
                        return local_x, local_y, local_z

                    if b1.horn_type_id == 3:  # Scorpion - left claw moves opposite
                        _, _, rel_z = get_local_collision(b1, collision_x, collision_y, collision_z)
                        if rel_z < -1.0:  # Left claw - inverted motion
                            b1_effective_vel = -b1.horn_pitch_velocity
                    elif b1.horn_type_id == 2:  # Hercules - top horn uses yaw velocity
                        rel_x, rel_y, _ = get_local_collision(b1, collision_x, collision_y, collision_z)
                        is_bottom_horn = rel_y < 5 or (rel_y < 8 and rel_x >= 10.0)
                        if not is_bottom_horn:  # Top horn - use yaw movement as effective velocity
                            b1_effective_vel = abs(b1.horn_yaw_velocity) * 0.4
                    elif b1.horn_type_id == 4:  # Atlas - side horns are fixed
                        _, _, rel_z = get_local_collision(b1, collision_x, collision_y, collision_z)
                        if abs(rel_z) > 1.5:  # Side pronotum horns - no velocity
                            b1_effective_vel = 0.0

                    if b2.horn_type_id == 3:  # Scorpion - left claw moves opposite
                        _, _, rel_z = get_local_collision(b2, collision_x, collision_y, collision_z)
                        if rel_z < -1.0:  # Left claw - inverted motion
                            b2_effective_vel = -b2.horn_pitch_velocity
                    elif b2.horn_type_id == 2:  # Hercules - top horn uses yaw velocity
                        rel_x, rel_y, _ = get_local_collision(b2, collision_x, collision_y, collision_z)
                        is_bottom_horn = rel_y < 5 or (rel_y < 8 and rel_x >= 10.0)
                        if not is_bottom_horn:  # Top horn - use yaw movement as effective velocity
                            b2_effective_vel = abs(b2.horn_yaw_velocity) * 0.4
                    elif b2.horn_type_id == 4:  # Atlas - side horns are fixed
                        _, _, rel_z = get_local_collision(b2, collision_x, collision_y, collision_z)
                        if abs(rel_z) > 1.5:  # Side pronotum horns - no velocity
                            b2_effective_vel = 0.0

                    lift_advantage = b1_effective_vel - b2_effective_vel

                    # DEBUG: Print collision info
                    # print(f"HORN COLLISION:")
                    # print(f"  Blue: vel={b1.horn_pitch_velocity:.2f}, y={b1.y:.1f}")
                    # print(f"  Red:  vel={b2.horn_pitch_velocity:.2f}, y={b2.y:.1f}")
                    # print(f"  Lift advantage: {lift_advantage:.2f} (>0 = Blue lifts Red, <0 = Red lifts Blue)")

                    # Very low threshold - almost any velocity difference triggers
                    ADVANTAGE_THRESHOLD = 0.5
                    LIFT_COOLDOWN_DURATION = 0.1  # Seconds between lift applications

                    # Calculate height penalty (reduces lift when beetles are already airborne)
                    NORMAL_HEIGHT = 2.0  # Height where lifts start weakening (lower = earlier penalty)
                    HEIGHT_PENALTY_FACTOR = 0.35  # How quickly lift weakens with height (higher = steeper)
                    avg_height = (b1.y + b2.y) / 2.0
                    height_penalty = 1.0
                    if avg_height > NORMAL_HEIGHT:
                        height_above_normal = avg_height - NORMAL_HEIGHT
                        height_penalty = 1.0 / (1.0 + height_above_normal * HEIGHT_PENALTY_FACTOR)

                    # Detect "pressing down" scenario: one beetle lowering horn into idle opponent
                    # In this case, the presser should have reduced self-effect and push the opponent
                    b1_pressing_down = b1_effective_vel < -0.3 and abs(b2_effective_vel) < 0.3
                    b2_pressing_down = b2_effective_vel < -0.3 and abs(b1_effective_vel) < 0.3
                    PRESS_DOWN_SELF_MULT = 0.15  # Reduced self-lift when pressing down (15% of normal)
                    PRESS_DOWN_PUSH_MULT = 0.5   # How much force transfers to opponent as push

                    # Check if both beetles are off cooldown before applying lift forces
                    # DELIVERY SPLIT (2026-07-07): the press-down wedge and the
                    # evenly-matched push are CONTINUOUS per-step forces now.
                    # They were 0.1s-cooldown pulse trains - pressing your tip
                    # down onto an idle opponent's tip made you hop in
                    # awkward, delayed jumps. Same average force (one pulse
                    # spread over the ~6 steps the cooldown covered), applied
                    # smoothly from the first contact step, no cooldown. The
                    # true advantage LAUNCH (lifting the opponent) stays
                    # pulsed - that one should feel like an event.
                    LIFT_STEP_DIV = 9.0  # Higher = gentler continuous lifts (6 = exact old average force)
                    lift_force_full = lift_impulse * params.get("HORN_LIFT_STRENGTH", 0.195) * height_penalty
                    tumble_mult = params.get("TUMBLE_MULTIPLIER", 3.0)

                    if lift_advantage > ADVANTAGE_THRESHOLD and b2_pressing_down:
                        # b2 presses down onto passive b1: smooth self-wedge
                        # up for b2, continuous horizontal push on b1
                        _f = lift_force_full / LIFT_STEP_DIV
                        b2.pending_lift += min(_f * PRESS_DOWN_SELF_MULT, 12.0 / LIFT_STEP_DIV)
                        push_h = _f * PRESS_DOWN_PUSH_MULT
                        b1.vx += normal_x * push_h
                        b1.vz += normal_z * push_h
                        world_lever_x = collision_x - b2.x
                        world_lever_z = collision_z - b2.z
                        cos_r = math.cos(b2.rotation)
                        sin_r = math.sin(b2.rotation)
                        local_x = world_lever_x * cos_r + world_lever_z * sin_r
                        local_z = world_lever_z * cos_r - world_lever_x * sin_r
                        b2.pending_pitch += (local_z * _f * tumble_mult * PRESS_DOWN_SELF_MULT) / b2.pitch_inertia
                        b2.pending_roll += (local_x * _f * tumble_mult * PRESS_DOWN_SELF_MULT) / b2.roll_inertia

                    elif lift_advantage < -ADVANTAGE_THRESHOLD and b1_pressing_down:
                        # b1 presses down onto passive b2 (mirror)
                        _f = lift_force_full / LIFT_STEP_DIV
                        b1.pending_lift += min(_f * PRESS_DOWN_SELF_MULT, 12.0 / LIFT_STEP_DIV)
                        push_h = _f * PRESS_DOWN_PUSH_MULT
                        b2.vx -= normal_x * push_h
                        b2.vz -= normal_z * push_h
                        world_lever_x = collision_x - b1.x
                        world_lever_z = collision_z - b1.z
                        cos_r = math.cos(b1.rotation)
                        sin_r = math.sin(b1.rotation)
                        local_x = world_lever_x * cos_r + world_lever_z * sin_r
                        local_z = world_lever_z * cos_r - world_lever_x * sin_r
                        b1.pending_pitch += (local_z * _f * tumble_mult * PRESS_DOWN_SELF_MULT) / b1.pitch_inertia
                        b1.pending_roll += (local_x * _f * tumble_mult * PRESS_DOWN_SELF_MULT) / b1.roll_inertia

                    elif abs(lift_advantage) <= ADVANTAGE_THRESHOLD:
                        # Evenly matched - smooth continuous mutual push
                        _f = lift_impulse * 0.06 * height_penalty / LIFT_STEP_DIV
                        _f_cap = min(_f, 12.0 / LIFT_STEP_DIV)
                        b1.pending_lift += _f_cap
                        b2.pending_lift += _f_cap

                        world_lever_x1 = collision_x - b1.x
                        world_lever_z1 = collision_z - b1.z
                        cos_r1 = math.cos(b1.rotation)
                        sin_r1 = math.sin(b1.rotation)
                        local_x1 = world_lever_x1 * cos_r1 + world_lever_z1 * sin_r1
                        local_z1 = world_lever_z1 * cos_r1 - world_lever_x1 * sin_r1
                        b1.pending_pitch += (-local_z1 * _f) / b1.pitch_inertia
                        b1.pending_roll += (local_x1 * _f) / b1.roll_inertia

                        world_lever_x2 = collision_x - b2.x
                        world_lever_z2 = collision_z - b2.z
                        cos_r2 = math.cos(b2.rotation)
                        sin_r2 = math.sin(b2.rotation)
                        local_x2 = world_lever_x2 * cos_r2 + world_lever_z2 * sin_r2
                        local_z2 = world_lever_z2 * cos_r2 - world_lever_x2 * sin_r2
                        b2.pending_pitch += (-local_z2 * _f) / b2.pitch_inertia
                        b2.pending_roll += (local_x2 * _f) / b2.roll_inertia

                    elif lift_advantage > ADVANTAGE_THRESHOLD:
                        # ADVANTAGE LIFT (continuous, 2026-07-07): b1 actively
                        # out-lifts b2. Also converted from the 0.1s pulse to
                        # a per-step stream - same force per unit time, and
                        # it responds every step instead of waiting out a
                        # cooldown mid-battle. Whole lift system is smooth now.
                        _f = lift_force_full / LIFT_STEP_DIV
                        b2.pending_lift += min(_f, 12.0 / LIFT_STEP_DIV)
                        b1.vy -= lift_impulse * 0.03 / LIFT_STEP_DIV  # Reaction

                        world_lever_x = collision_x - b2.x
                        world_lever_z = collision_z - b2.z
                        cos_r = math.cos(b2.rotation)
                        sin_r = math.sin(b2.rotation)
                        local_x = world_lever_x * cos_r + world_lever_z * sin_r
                        local_z = world_lever_z * cos_r - world_lever_x * sin_r
                        b2.pending_pitch += (local_z * _f * tumble_mult) / b2.pitch_inertia
                        b2.pending_roll += (local_x * _f * tumble_mult) / b2.roll_inertia
                    else:
                        # b2 actively out-lifts b1 (mirror, continuous)
                        _f = lift_force_full / LIFT_STEP_DIV
                        b1.pending_lift += min(_f, 12.0 / LIFT_STEP_DIV)
                        b2.vy -= lift_impulse * 0.03 / LIFT_STEP_DIV  # Reaction

                        world_lever_x = collision_x - b1.x
                        world_lever_z = collision_z - b1.z
                        cos_r = math.cos(b1.rotation)
                        sin_r = math.sin(b1.rotation)
                        local_x = world_lever_x * cos_r + world_lever_z * sin_r
                        local_z = world_lever_z * cos_r - world_lever_x * sin_r
                        b1.pending_pitch += (local_z * _f * tumble_mult) / b1.pitch_inertia
                        b1.pending_roll += (local_x * _f * tumble_mult) / b1.roll_inertia

                    # Add horizontal spin based on where horn hit BOTH beetles
                    # Calculate lever arms from beetle centers to collision point
                    dx_to_b1 = collision_x - b1.x
                    dz_to_b1 = collision_z - b1.z
                    dx_to_b2 = collision_x - b2.x
                    dz_to_b2 = collision_z - b2.z

                    # Calculate tangential velocity at collision point (perpendicular to normal)
                    # This captures rotation effects even when linear velocity is small
                    # (rotation convention: world = R(th)*local with R=[[c,-s],[s,c]],
                    # so a point at offset (dx, dz) moves at omega*(-dz, +dx))
                    v1_at_collision_x = b1.vx - dz_to_b1 * b1.angular_velocity
                    v1_at_collision_z = b1.vz + dx_to_b1 * b1.angular_velocity
                    v2_at_collision_x = b2.vx - dz_to_b2 * b2.angular_velocity
                    v2_at_collision_z = b2.vz + dx_to_b2 * b2.angular_velocity

                    # Relative velocity at collision point
                    rel_vx = v1_at_collision_x - v2_at_collision_x
                    rel_vz = v1_at_collision_z - v2_at_collision_z

                    # Calculate tangential component (perpendicular to normal) for spin torque
                    # Project onto tangent direction (perpendicular to normal)
                    tangent_x = -normal_z
                    tangent_z = normal_x
                    rel_vel_tangent = rel_vx * tangent_x + rel_vz * tangent_z

                    # Hybrid approach: base torque from geometry + velocity modulation
                    # This ensures torque always exists but scales with collision dynamics
                    base_torque_b1 = dx_to_b1 * normal_z - dz_to_b1 * normal_x
                    base_torque_b2 = dx_to_b2 * normal_z - dz_to_b2 * normal_x

                    # Modulate by tangential velocity (captures rotation into each other)
                    # Add baseline factor to ensure minimum torque even when stationary
                    velocity_factor = 1.0 + abs(rel_vel_tangent) * 0.5

                    torque_b1 = base_torque_b1 * velocity_factor
                    torque_b2 = base_torque_b2 * velocity_factor

                    # Apply angular impulses with horn leverage (smoothed)
                    angular_impulse_b1 = (torque_b1 / b1.moment_of_inertia) * horn_leverage * 1.3
                    angular_impulse_b2 = (torque_b2 / b2.moment_of_inertia) * horn_leverage * 1.3
                    b1.pending_yaw += angular_impulse_b1
                    b2.pending_yaw -= angular_impulse_b2

                    # AWAY-FROM-ATTACKER BIAS: Ensure hit beetle spins away from attacker
                    # This fixes counterintuitive behavior where shaft hits cause turning INTO attacker
                    # Velocity AT the contact point, so sweeping your horn into
                    # someone by turning counts as attacking, not just driving
                    b1_toward_bias = v1_at_collision_x * (-normal_x) + v1_at_collision_z * (-normal_z)
                    b2_toward_bias = v2_at_collision_x * normal_x + v2_at_collision_z * normal_z
                    b1_toward_bias = max(b1_toward_bias, 0.0)
                    b2_toward_bias = max(b2_toward_bias, 0.0)

                    bias_strength = params.get("COLLISION_SPIN_BIAS", 0.8)

                    # TIP vs SHAFT: Shaft hits need MORE spin bias to counteract wrong-direction torque
                    if has_horn_tips == 0:
                        shaft_spin_mult = params.get("SHAFT_SPIN_BIAS_MULT", 2.0)
                        bias_strength *= shaft_spin_mult

                    # b1 is attacking b2 - make b2 spin away from b1
                    if b1_toward_bias > b2_toward_bias + 0.5:
                        # Calculate angle from b2 to b1 (attack direction)
                        attack_angle = math.atan2(-normal_z, -normal_x)
                        victim_facing = b2.rotation
                        angle_diff = attack_angle - victim_facing
                        # Normalize to [-pi, pi]
                        while angle_diff > math.pi: angle_diff -= TWO_PI
                        while angle_diff < -math.pi: angle_diff += TWO_PI

                        # Spin direction to turn nose away from attacker
                        away_spin = -1.0 if angle_diff > 0 else 1.0

                        # Scale by momentum difference
                        momentum_factor = (b1_toward_bias - b2_toward_bias) / (b1_toward_bias + b2_toward_bias + 0.01)
                        bias_torque = away_spin * bias_strength * momentum_factor * horn_leverage
                        b2.pending_yaw += bias_torque / b2.moment_of_inertia

                    # b2 is attacking b1 - make b1 spin away from b2
                    elif b2_toward_bias > b1_toward_bias + 0.5:
                        attack_angle = math.atan2(normal_z, normal_x)
                        victim_facing = b1.rotation
                        angle_diff = attack_angle - victim_facing
                        while angle_diff > math.pi: angle_diff -= TWO_PI
                        while angle_diff < -math.pi: angle_diff += TWO_PI

                        away_spin = -1.0 if angle_diff > 0 else 1.0

                        momentum_factor = (b2_toward_bias - b1_toward_bias) / (b1_toward_bias + b2_toward_bias + 0.01)
                        bias_torque = away_spin * bias_strength * momentum_factor * horn_leverage
                        b1.pending_yaw += bias_torque / b1.moment_of_inertia

            # Separation/tipping to prevent stuck collisions
            separation_force = params["SEPARATION_FORCE"]

            if is_horn_contact and not is_ball_collision:
                # HORN COLLISION: Apply tipping torque instead of full separation
                # Use separate cooldown from lift forces (0.1 seconds)
                if b1.tip_cooldown <= 0.0 and b2.tip_cooldown <= 0.0:
                    tip_strength = params.get("HORN_TIP_STRENGTH", 2.0)

                    # MOMENTUM-BASED TIPPING: Beetle with more momentum tips the other more
                    # Momentum measured at the contact point: horn sweeps from turning
                    # count, and a victim rotating with the blow yields less
                    tip_cv1_x = b1.vx - (collision_z - b1.z) * b1.angular_velocity
                    tip_cv1_z = b1.vz + (collision_x - b1.x) * b1.angular_velocity
                    tip_cv2_x = b2.vx - (collision_z - b2.z) * b2.angular_velocity
                    tip_cv2_z = b2.vz + (collision_x - b2.x) * b2.angular_velocity
                    b1_toward = tip_cv1_x * (-normal_x) + tip_cv1_z * (-normal_z)
                    b2_toward = tip_cv2_x * normal_x + tip_cv2_z * normal_z
                    b1_toward = max(b1_toward, 0.0)
                    b2_toward = max(b2_toward, 0.0)
                    total_momentum = b1_toward + b2_toward + 0.01

                    # b1 gets tipped by b2's momentum, b2 gets tipped by b1's momentum
                    # Range from 0.5x to 1.5x base tip strength
                    b1_tip_received = tip_strength * (0.5 + (b2_toward / total_momentum))
                    b2_tip_received = tip_strength * (0.5 + (b1_toward / total_momentum))

                    # Lever arms in beetle's LOCAL space (not arena coords)
                    # Beetle 1
                    world_lever1_x = collision_x - b1.x
                    world_lever1_z = collision_z - b1.z
                    cos_r1 = math.cos(b1.rotation)
                    sin_r1 = math.sin(b1.rotation)
                    local1_x = world_lever1_x * cos_r1 + world_lever1_z * sin_r1  # left/right
                    local1_z = world_lever1_z * cos_r1 - world_lever1_x * sin_r1  # front/back

                    # Beetle 2
                    world_lever2_x = collision_x - b2.x
                    world_lever2_z = collision_z - b2.z
                    cos_r2 = math.cos(b2.rotation)
                    sin_r2 = math.sin(b2.rotation)
                    local2_x = world_lever2_x * cos_r2 + world_lever2_z * sin_r2  # left/right
                    local2_z = world_lever2_z * cos_r2 - world_lever2_x * sin_r2  # front/back

                    # Pitch torque (collision in front tips nose up - both beetles tip back)
                    b1.pending_pitch += local1_z * b1_tip_received / b1.pitch_inertia
                    b2.pending_pitch += local2_z * b2_tip_received / b2.pitch_inertia

                    # Roll torque (collision to the side tips away - both beetles tip away)
                    b1.pending_roll -= local1_x * b1_tip_received / b1.roll_inertia
                    b2.pending_roll -= local2_x * b2_tip_received / b2.roll_inertia

                    # Yaw torque (tangential spin) - disabled for now, already handled by horn leverage
                    yaw_factor = 0.0
                    b1.angular_velocity += (local1_x * normal_z - local1_z * normal_x) * b1_tip_received * yaw_factor
                    b2.angular_velocity -= (local2_x * normal_z - local2_z * normal_x) * b2_tip_received * yaw_factor

                    # Set tip cooldown (separate from lift forces)
                    b1.tip_cooldown = 0.03
                    b2.tip_cooldown = 0.03

                # Reduced separation for horns (20% of normal to prevent complete overlap)
                # Applied every frame regardless of cooldown
                # TIP vs SHAFT: Shaft hits need MORE separation to prevent clipping
                if has_horn_tips == 1:
                    mini_sep = separation_force * 0.2  # Tips: 20% separation (they lock well)
                else:
                    shaft_sep_mult = params.get("SHAFT_SEPARATION_MULT", 0.5)
                    mini_sep = separation_force * shaft_sep_mult  # Shaft: more separation to prevent clip

                # MOMENTUM-BASED SEPARATION: Moving beetle pushes stationary one more
                # Measured at the contact point so horn sweeps from turning push too
                sep_cv1_x = b1.vx - (collision_z - b1.z) * b1.angular_velocity
                sep_cv1_z = b1.vz + (collision_x - b1.x) * b1.angular_velocity
                sep_cv2_x = b2.vx - (collision_z - b2.z) * b2.angular_velocity
                sep_cv2_z = b2.vz + (collision_x - b2.x) * b2.angular_velocity
                b1_toward = sep_cv1_x * (-normal_x) + sep_cv1_z * (-normal_z)  # b1 moving toward b2
                b2_toward = sep_cv2_x * normal_x + sep_cv2_z * normal_z        # b2 moving toward b1

                # Clamp to positive (only count forward momentum)
                b1_toward = max(b1_toward, 0.0)
                b2_toward = max(b2_toward, 0.0)

                # Calculate momentum ratio (who's pushing harder)
                total_momentum = b1_toward + b2_toward + 0.01  # small epsilon to avoid div by zero

                # Harder approach pushes harder: scale separation with closing
                # momentum (capped at 2x) instead of a constant-strength shove
                mini_sep *= 1.0 + min(total_momentum * params.get("SEPARATION_MOMENTUM_SCALE", 0.06), 1.0)
                b1_push_ratio = b1_toward / total_momentum  # 0-1, how much b1 is pushing
                b2_push_ratio = b2_toward / total_momentum  # 0-1, how much b2 is pushing

                # Distribute separation: pusher gets less pushback, pushed gets more
                # Range from 0.3x to 1.7x of base separation
                b1_sep = mini_sep * (1.7 - b1_push_ratio * 1.4)
                b2_sep = mini_sep * (1.7 - b2_push_ratio * 1.4)

                b1.x += normal_x * b1_sep
                b1.z += normal_z * b1_sep
                b2.x -= normal_x * b2_sep
                b2.z -= normal_z * b2_sep
            else:
                # BODY COLLISION or BALL: Keep full separation behavior with momentum
                b1_toward = b1.vx * (-normal_x) + b1.vz * (-normal_z)
                b2_toward = b2.vx * normal_x + b2.vz * normal_z

                # For ball collisions, include angular velocity contribution to momentum
                # This ensures rotating the horn into the ball transfers momentum properly
                if is_ball_collision:
                    horn_reach = 15.0  # Distance from beetle center to horn tip
                    # Check which beetle is the ball
                    if b1.horn_type != "ball":
                        # b1 is the beetle - add its rotation momentum
                        tip_tangent = abs(b1.angular_velocity) * horn_reach
                        b1_toward = max(b1_toward, tip_tangent * 0.7)
                    if b2.horn_type != "ball":
                        # b2 is the beetle - add its rotation momentum
                        tip_tangent = abs(b2.angular_velocity) * horn_reach
                        b2_toward = max(b2_toward, tip_tangent * 0.7)

                b1_toward = max(b1_toward, 0.0)
                b2_toward = max(b2_toward, 0.0)
                total_momentum = b1_toward + b2_toward + 0.01
                b1_push_ratio = b1_toward / total_momentum
                b2_push_ratio = b2_toward / total_momentum

                # Body-to-body: 70% weaker separation (0.3x), ball keeps full separation
                body_sep_mult = 0.3 if not is_ball_collision else 1.0
                b1_sep = separation_force * body_sep_mult * (1.7 - b1_push_ratio * 1.4)
                b2_sep = separation_force * body_sep_mult * (1.7 - b2_push_ratio * 1.4)

                b1.x += normal_x * b1_sep
                b1.z += normal_z * b1_sep
                b2.x -= normal_x * b2_sep
                b2.z -= normal_z * b2_sep

                # BODY COLLISION TILT: Bodies tilt in opposite directions on impact
                if not is_ball_collision:
                    body_tilt_strength = params.get("BODY_TILT_STRENGTH", 1.2)

                    # Calculate lever arms in each beetle's local space
                    world_lever1_x = collision_x - b1.x
                    world_lever1_z = collision_z - b1.z
                    cos_r1 = math.cos(b1.rotation)
                    sin_r1 = math.sin(b1.rotation)
                    local1_x = world_lever1_x * cos_r1 + world_lever1_z * sin_r1  # left/right
                    local1_z = world_lever1_z * cos_r1 - world_lever1_x * sin_r1  # front/back

                    world_lever2_x = collision_x - b2.x
                    world_lever2_z = collision_z - b2.z
                    cos_r2 = math.cos(b2.rotation)
                    sin_r2 = math.sin(b2.rotation)
                    local2_x = world_lever2_x * cos_r2 + world_lever2_z * sin_r2
                    local2_z = world_lever2_z * cos_r2 - world_lever2_x * sin_r2

                    # Scale tilt by momentum (pusher tips less, pushed tips more)
                    b1_tilt = body_tilt_strength * (1.5 - b1_push_ratio)
                    b2_tilt = body_tilt_strength * (1.5 - b2_push_ratio)

                    # Pitch: opposite directions (one tips forward, other tips back)
                    b1.pitch_velocity += local1_z * b1_tilt / b1.pitch_inertia
                    b2.pitch_velocity -= local2_z * b2_tilt / b2.pitch_inertia  # Opposite sign

                    # Roll: both tilt away from collision point
                    b1.roll_velocity -= local1_x * b1_tilt / b1.roll_inertia
                    b2.roll_velocity += local2_x * b2_tilt / b2.roll_inertia  # Opposite sign

            # VERTICAL SEPARATION - only when both beetles are airborne
            # This prevents floor voxel destruction and maintains symmetry
            if not b1.on_ground and not b2.on_ground:
                b1.y += normal_y * separation_force
                b2.y -= normal_y * separation_force
                # Update prev positions to prevent interpolation choppiness from position corrections
                # (Ball especially needs this for smooth vertical motion during collisions)
                if is_ball_collision:
                    if b1.horn_type == "ball":
                        b1.prev_y = b1.y
                    if b2.horn_type == "ball":
                        b2.prev_y = b2.y

            # Safety clamp to prevent going below floor voxel layer
            # (Main floor collision handles proper positioning above floor)
            MIN_Y = 0.5  # Minimum Y to prevent center going below floor at y=0
            if b1.y < MIN_Y:
                b1.y = MIN_Y
                b1.vy = 0.0
            if b2.y < MIN_Y:
                b2.y = MIN_Y
                b2.vy = 0.0

            # Calculate 3D relative velocity
            rel_vx = b1.vx - b2.vx
            rel_vy = b1.vy - b2.vy
            rel_vz = b1.vz - b2.vz
            vel_along_normal = rel_vx * normal_x + rel_vy * normal_y + rel_vz * normal_z

            # For ball collisions: allow redirection even when ball is moving away (airborne hits)
            # For beetle collisions: only apply impulse if moving toward each other
            apply_impulse = vel_along_normal < 0  # Default: only when approaching
            if is_ball_collision and vel_along_normal >= 0:
                # Ball is moving away - still apply a redirection impulse based on beetle velocity
                # This allows "steering" the ball mid-air by hitting it from a new angle
                apply_impulse = True
                # Use beetle's velocity projected onto collision normal as the impulse basis
                # This makes the ball respond to where the beetle is pushing, not relative motion
                if b1.horn_type == "ball":
                    beetle = b2
                    ball = b1
                    beetle_vel_along_normal = -(beetle.vx * normal_x + beetle.vz * normal_z)
                else:
                    beetle = b1
                    ball = b2
                    beetle_vel_along_normal = beetle.vx * normal_x + beetle.vz * normal_z
                
                # Also consider horn tip velocity from rotation
                # When beetle rotates, horn tip moves even if beetle center doesn't
                # Tip velocity = angular_velocity * distance_from_center (perpendicular to radius)
                horn_reach = 15.0  # Approximate horn length
                # Tangential velocity at horn tip from rotation
                tip_tangent_speed = abs(beetle.angular_velocity) * horn_reach
                # If rotating significantly, treat as active movement toward ball
                if tip_tangent_speed > 1.0:
                    beetle_vel_along_normal = max(abs(beetle_vel_along_normal), tip_tangent_speed * 0.5)
                
                # Override vel_along_normal with beetle's push direction (negative = toward ball)
                if abs(beetle_vel_along_normal) > 0.3:  # Lower threshold, rotation counts
                    vel_along_normal = -abs(beetle_vel_along_normal) * 0.8  # Treat as approaching

            if apply_impulse:
                # Impulse magnitude (use ball-specific restitution for ball collisions)
                if is_ball_collision:
                    # Ball collision: use ball restitution and momentum transfer
                    restitution = params["BALL_RESTITUTION"]
                    impulse = -(1 + restitution) * vel_along_normal * params["BALL_MOMENTUM_TRANSFER"]
                else:
                    # Beetle collision: use beetle combat physics
                    impulse = -(1 + params["RESTITUTION"]) * vel_along_normal * params["IMPULSE_MULTIPLIER"]

                # Apply 3D linear impulse
                impulse_x = impulse * normal_x
                impulse_z = impulse * normal_z

                # For horn contact, lifting logic handles vertical forces explicitly
                # Only apply vertical impulse for non-horn collisions
                if is_horn_contact:
                    impulse_y = 0.0  # Disable vertical impulse - lifting logic handles it
                else:
                    impulse_y = impulse * normal_y

                b1.vx += impulse_x
                b1.vy += impulse_y
                b1.vz += impulse_z
                b2.vx -= impulse_x
                b2.vy -= impulse_y
                b2.vz -= impulse_z

                # Calculate and apply torque (angular impulse)
                # Torque = r × F (cross product in 2D: rx*Fz - rz*Fx)

                # For beetle 1: collision point relative to its center
                r1_x = collision_x - b1.x
                r1_z = collision_z - b1.z
                torque1 = r1_x * impulse_z - r1_z * impulse_x
                angular_impulse1 = (torque1 / b1.moment_of_inertia) * params["TORQUE_MULTIPLIER"]
                b1.angular_velocity += angular_impulse1

                # For beetle 2: collision point relative to its center
                r2_x = collision_x - b2.x
                r2_z = collision_z - b2.z
                torque2 = r2_x * (-impulse_z) - r2_z * (-impulse_x)
                angular_impulse2 = (torque2 / b2.moment_of_inertia) * params["TORQUE_MULTIPLIER"]
                b2.angular_velocity += angular_impulse2

                # === BALL PHYSICS: TORQUE/LIFT/TIP (realistic contact-based forces) ===
                # Apply special physics when ball is involved (hit from side = spin, from below = lift, from above = tip)
                if is_ball_collision:
                    # Identify which entity is the ball
                    if b1.horn_type == "ball":
                        ball = b1
                        beetle = b2
                        ball_is_b1 = True
                    else:
                        ball = b2
                        beetle = b1
                        ball_is_b1 = False

                    # Get push and spin multipliers for lighter/heavier ball feel
                    push_mult = params["BALL_PUSH_MULTIPLIER"]
                    spin_mult = params["BALL_SPIN_MULTIPLIER"]

                    # Apply extra push force to ball based on push multiplier
                    # This makes the ball feel lighter and easier to push
                    if ball_is_b1:
                        ball.vx += impulse_x * (push_mult - 1.0)  # Extra push on top of normal impulse
                        ball.vz += impulse_z * (push_mult - 1.0)
                    else:
                        ball.vx -= impulse_x * (push_mult - 1.0)
                        ball.vz -= impulse_z * (push_mult - 1.0)

                    # Calculate contact offset from ball center (Y-axis for lift/tip)
                    contact_offset_y = collision_y - ball.y

                    # HORN SCOOP LIFT: When beetle tilts horn UP while touching bottom of ball, lift it!
                    # This mimics beetle-to-beetle combat where horn pitch velocity determines lift
                    if contact_offset_y < ball.radius * 0.3:  # Contact at or below ball center (bottom 80%)
                        # Check if beetle is actively tilting horn upward (positive horn_pitch_velocity)
                        if beetle.horn_pitch_velocity > 0.5 and beetle.lift_cooldown <= 0.0:  # Beetle is scooping up
                            # Scale lift force by horn velocity (more aggressive scoop = more lift)
                            scoop_strength = min(beetle.horn_pitch_velocity / 2.0, 1.5)  # Cap at 1.5x
                            horn_scoop_lift = params["BALL_LIFT_STRENGTH"] * 2.0 * scoop_strength * push_mult
                            ball.vy += horn_scoop_lift
                            beetle.lift_cooldown = 0.05  # Prevent rapid-fire ball scooping

                    # PASSIVE LIFT: Hit from below (contact point is below ball center)
                    # Base upward force when beetle pushes ball from below
                    if contact_offset_y < -ball.radius * 0.35:  # Bottom 15% of ball
                        lift_force = params["BALL_PASSIVE_LIFT_STRENGTH"] * push_mult
                        ball.vy += lift_force

                    # TIP: Hit from above (contact point is above ball center)
                    # When beetle hits ball from above, push it down
                    elif contact_offset_y > ball.radius * 0.2:  # Top 20% of ball
                        tip_force = params["BALL_TIP_STRENGTH"]
                        ball.vy -= tip_force

                    # TORQUE: Hits create spin on all 3 axes based on contact point
                    # Calculate offset from ball center (contact_offset_y already calculated above)
                    contact_offset_x = collision_x - ball.x
                    contact_offset_z = collision_z - ball.z

                    # Apply rotational spin based on impact location
                    # Torque = r × F (lever arm cross force)
                    # Use spin_mult to make ball spin easier
                    torque_strength = params["BALL_TORQUE_STRENGTH"] * spin_mult / ball.moment_of_inertia

                    # YAW spin (around Y axis) - from horizontal offset
                    ball_yaw_torque = contact_offset_x * impulse_z - contact_offset_z * impulse_x
                    ball_yaw_impulse = ball_yaw_torque * torque_strength

                    # PITCH spin (around Z axis) - from vertical offset with forward/back force
                    # Hit from above + pushed forward = topspin (pitch forward)
                    # Hit from below + pushed forward = backspin (pitch backward)
                    ball_pitch_torque = contact_offset_y * impulse_x
                    ball_pitch_impulse = ball_pitch_torque * torque_strength * 0.2

                    # ROLL spin (around X axis) - from vertical offset with side force
                    ball_roll_torque = contact_offset_y * impulse_z
                    ball_roll_impulse = ball_roll_torque * torque_strength * 0.2

                    # Apply all torques (add to existing angular velocity for realistic spin accumulation)
                    if ball_is_b1:
                        ball.angular_velocity += ball_yaw_impulse
                        ball.pitch_velocity += ball_pitch_impulse
                        ball.roll_velocity += ball_roll_impulse
                    else:
                        ball.angular_velocity -= ball_yaw_impulse  # Reverse sign for b2
                        ball.pitch_velocity -= ball_pitch_impulse
                        ball.roll_velocity -= ball_roll_impulse

            # === PHASE 3: BODY ROTATION DAMPING ===
            # Track collision-induced spin direction and set damping
            # This prevents immediate rotation into collision direction, preventing horn clipping

            # For beetle 1: if angular_velocity is significant, apply damping
            if abs(b1.angular_velocity) > 0.3:  # Lower threshold for more responsiveness
                # Store spin direction: 1 = clockwise (positive), -1 = counterclockwise (negative)
                b1.collision_spin_direction = 1 if b1.angular_velocity > 0 else -1
                # Apply full damping strength on any significant collision
                b1.body_rotation_damping = BODY_ROTATION_DAMPING_STRENGTH

            # For beetle 2: same logic
            if abs(b2.angular_velocity) > 0.3:
                b2.collision_spin_direction = 1 if b2.angular_velocity > 0 else -1
                # Apply full damping strength on any significant collision
                b2.body_rotation_damping = BODY_ROTATION_DAMPING_STRENGTH

            # === CLAMP ANGULAR VELOCITY IMMEDIATELY ===
            # Prevents huge rotation jumps on next frame before update_physics clamps
            # Without this, angular_velocity can exceed MAX_ANGULAR_SPEED and cause
            # jarring 180-degree spins when the unclamped value is applied to rotation
            if abs(b1.angular_velocity) > MAX_ANGULAR_SPEED:
                b1.angular_velocity = MAX_ANGULAR_SPEED if b1.angular_velocity > 0 else -MAX_ANGULAR_SPEED
            if abs(b2.angular_velocity) > MAX_ANGULAR_SPEED:
                b2.angular_velocity = MAX_ANGULAR_SPEED if b2.angular_velocity > 0 else -MAX_ANGULAR_SPEED
    else:
        # No collision - reset smoothed collision normals
        b1.contact_normal_x = 0.0
        b1.contact_normal_y = 0.0
        b1.contact_normal_z = 0.0
        b2.contact_normal_x = 0.0
        b2.contact_normal_y = 0.0
        b2.contact_normal_z = 0.0

def normalize_angle(angle):
    """Normalize angle to [0, 2π)"""
    while angle < 0:
        angle += TWO_PI
    while angle >= TWO_PI:
        angle -= TWO_PI
    return angle

def shortest_rotation(current, target):
    """Find shortest rotation from current to target"""
    current = normalize_angle(current)
    target = normalize_angle(target)
    diff = target - current
    if diff > math.pi:
        diff -= TWO_PI
    elif diff < -math.pi:
        diff += TWO_PI
    return diff

